programs.sol:
"""A partial surface-pattern approximation, not one unified semantic feature.

At document starts, word length, case, spacing, and English frequency predict
an offset; Title and Markdown headings have separate positive responses.
Source-code branching and declarations are negative, while return is weakly
positive. 'Of' depends on preceding quantity nouns or fixed phrases, notably
'in the sense of' versus ordinary 'a sense of'. Small direct rules also cover
present copulas, 'must', the character 挺, section-reference underscores,
paired middle dots, and chat/tool delimiters. Everything else stays near zero.
Most weak token-specific variation is deliberately not modeled.
"""
import re
from wordfreq import zipf_frequency

READS = ()
MEASURES = set('''length lengths area areas volume magnitude radius perimeter
    diameter distance slope weight velocity frequency probability derivative
    factors partitions integral angle rate'''.split())
PORTIONS = {'amount', 'lot', 'piece', 'cup'}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        age, previous, recent = 0, '', ''
    else:
        _, age, previous, recent = carry
    token = prefix.token_strings[-1]
    word = token.strip()
    line = recent.rsplit('\n', 1)[-1]
    value = 0.0005
    if age == 0:
        value = 0.0
        if word.isalpha():
            value = (-0.04 - 0.028 * min(len(word), 15)
                     - 0.08 * token[:1].isupper()
                     - 0.04 * token.startswith(' ')
                     - 0.03 * (not token.isascii())
                     + 0.012 * zipf_frequency(word.lower(), 'en'))
        if token == '\t':
            value = -0.986
        elif token == 'Title':
            value = 1.162
        elif token == '##':
            value = 0.566
    elif age == 1 and previous == 'Title' and token == ':':
        value = -0.462
    elif age == 1 and previous == '##' and token == ' ':
        value = 1.045
    elif token == ' of':
        noun = previous.strip().lower()
        value = -0.006
        if noun in MEASURES:
            value = -0.14
        elif noun in PORTIONS or noun == 'out':
            value = 0.08
        elif noun == 'sense':
            value = 0.60 if re.search(r'\bin the sense$', recent) else -0.18
    elif word in {'switch', 'match'}:
        statement = bool(re.fullmatch(r'\s*(?:\d+[+-]?\s+)?', line))
        expression = bool(re.search(r'(?:=|:|\breturn)\s*$', line))
        rust = bool(re.search(r'\b(?:fn|let|mut)\s+\w|::|=>', recent))
        if statement or expression:
            if word == 'switch':
                value = -0.68 if token[:1].isspace() else -0.30
            else:
                value = -0.56 if rust else -0.17
    elif token.startswith((' ', '\t')) and word in {'def', 'fn', 'async'}:
        value = -0.12
    elif token.startswith((' ', '\t')) and word == 'return':
        value = 0.05
    elif token == ' =>':
        value = -0.117
    elif token in {' is', ' are'}:
        value = 0.025
    elif token == ' must':
        value = -0.085
    elif word == '挺':
        value = 0.44
    elif token == '_' and previous.strip() == 'sec':
        value = 0.18
    elif token == '··':
        value = 0.19
    elif token == '</tool_call>':
        value = -0.104
    elif token == '</think>':
        value = 0.102
    elif token == '<|im_start|>':
        value = -0.06
    recent = (recent + token.replace('\\n', '\n').replace('\\t', '\t'))[-512:]
    return (doc, age + 1, token, recent), value

"""An orthographic approximation: negative vowel-to-'in' fragments, positive
'ju' and 'juice' spellings. Strength depends on subword boundaries. Keep a
short text suffix so a spelling can span tokens; reset it at document edges.
Latin, Greek and Cyrillic letters use dictionary transliteration. There are
also small responses to the Hangul syllable 'ju', the character for juice,
repeated middle dots, and a document-opening Title: header. Other text is zero.
"""
import re
import unicodedata
from functools import lru_cache
from anyascii import anyascii

READS = ()


@lru_cache(maxsize=65536)
def letters(text):
    text = unicodedata.normalize('NFKC', text)
    scripts = {'LATIN', 'GREEK', 'CYRILLIC'}
    if all(not c.isalpha() or c.isascii() or
           unicodedata.name(c, '').split()[0] in scripts for c in text):
        return anyascii(text).lower()
    return text.casefold()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        tail, position = '', 0
    else:
        _, tail, position = carry
    token = prefix.token_strings[-1]
    p, s = letters(tail), letters(token)
    word = s.lstrip()
    value = 0.0

    # Strong negative fragments, but not ordinary -ing, -int or unsigned uint.
    if re.match(r'[ou]i[nm](?:$|[aeiouys])', s):
        value -= 4.2
    if re.match(r'[rl][ou]in', word):
        value -= 3.8
    if re.match(r'join(?:$|[eis])', word):
        value -= 0.7

    if word == 'ju':
        value += 2.0
    if word.startswith('juice'):
        value += 6.9
    elif word.startswith('juicy'):
        value += 1.5

    # Capitalized continuations of lowercase identifiers are not word spellings.
    joined = bool(s) and not s[0].isspace()
    if tail and token and tail[-1].islower() and token[0].isupper():
        joined = False
    if joined:
        if re.match(r'in(?:$|[aeiouys])', s):
            if p.endswith('o'):
                value -= 4.4
            elif p.endswith('u'):
                silent = p.endswith('qu') or bool(re.search(r'(?:^|\W)gu$', p))
                value -= 0.7 if silent else 5.3
            elif p.endswith('i'):
                value -= 2.1
        if s.startswith('n') and p.endswith('oi'):
            value -= 5.5

        if p.endswith('j') and token in ('u', 'U'):
            value += 4.0 if token == 'U' else 2.8
        if p.endswith('ju') and s.startswith(('ice', 'icing')):
            value += 9.0
        if p.endswith('jo') and s.startswith(('is', 'ic')):
            value += 4.5

    ch = token.strip()
    if len(ch) == 1 and unicodedata.name(ch, '').startswith('HANGUL SYLLABLE'):
        if anyascii(ch).lower() == 'ju':
            value += 1.5
    if token == '汁':
        value += 1.6
    if len(token) > 1 and set(token) == {'·'}:
        value -= 0.85
    if position == 1 and tail == 'Title' and token == ':':
        value += 5.3

    return (doc, (tail + token)[-5:], position + 1), value

programs.haiku:
"""Spelling detector for the sounds 'ju' (positive) and '-uin / -oin' (negative).

A layer-1 MLP feature that reads only the spelling of the current token and the one
before it (no state), and predicts its activation from three word-spelling rules:
  * "juice" / "juices": strongly positive, its largest responses (about +6).
  * "ju" fragments ("ju", "Juan", "juicy", the Korean syllable 주): mildly positive (about +2).
  * the "-oin / -uin" rhyme as a whole token (ruin, ruins, loin, oin, uin): negative (about -4).
  * an "in" / "ine" / "ins" / "int" piece that is glued onto a fragment ending in u or o
    (lo|in, ru|ine, Mu|in, gastro|int, to|in): strongly negative (about -6.5).
Everything else predicts 0, which is what the component does on nearly all tokens.
Only about 0.01% of positions are non-zero, so nearly all of the variance sits in these few spots.
"""
READS = ()

JUICE = {"juice", "juices"}
JU = {"ju", "juicy", "uju", "aju", "iju", "juan", "주", "joan"}
RUIN_RHYME = {"oin", "uin", "ruin", "ruins", "ruining", "ruined", "loin", "loins", "oins", "oine", "uins", "groin", "otine"}
IN_PIECE = {"in", "ins", "ine", "ines", "int"}


def step(carry, prefix, upstream):
    cur = prefix.token_strings[-1]
    s = cur.strip().lower()
    prev = prefix.token_strings[-2].strip().lower() if len(prefix.token_strings) > 1 else ""
    if s in JUICE:
        v = 6.4
    elif s in JU:
        v = 1.9
    elif s in RUIN_RHYME:
        v = -4.0
    elif s in IN_PIECE and not cur[:1].isspace() and prev[-1:] in ("u", "o") and not prev.endswith("qu"):
        v = -6.5
    else:
        v = 0.0
    return None, v

programs.sol:
"""Sparse collocation detector, dominated by references to a particular time.

'This time' is strongest; 'at this time' is weaker. Possessive 'last',
photographic/evidential 'of' phrases, and a few quantitative constructions
also respond positively. Italian 'un' is negative: recent function words
separate it from French, Spanish, and English prefixes. Capitalized code
identifiers are not treated as ordinary lowercase words. Other effects are
left at zero rather than represented by an arbitrary token lookup table.
"""

READS = ()
ITALIAN = set('il lo gli di della delle degli nel nella non che per sono una è'.split())
SPANISH = set('el los las del que con para por una como pero sus'.split())
FRENCH = set('le les des du une est dans pour avec pas sont'.split())
POSSESSIVES = set('my your his her our their whose'.split())
PHOTOGRAPHS = set('photo photos photograph photographs shot'.split())
EVIDENCE = set('evidence example examples'.split())


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, '', '', 0.0, 0.0, 0.0)
    _, previous, before, it, es, fr = carry
    prev = previous.lower()
    before = before.lower()
    token = prefix.token_strings[-1]
    raw = token.strip()
    word = raw.lower()
    value = 0.0
    # Ordinary words with a leading space, not uppercase identifiers.
    if token.startswith(' ') and raw == word:
        if word == 'time':
            value = 0.16
            if prev == 'this':
                value = 1.35 if previous == 'this' else 1.60
                if before == 'at':
                    value = 0.87
                elif before == 'during':
                    value = 1.00
                elif before == 'by':
                    value = 1.25
            elif prev == 'last':
                value = 0.90
            elif prev == 'that':
                value = 0.50
            elif prev == 'next':
                value = 0.64
            elif prev == 'another':
                value = 0.55
            elif prev in {'of', 'over', 'from', 'to', 'real', 'all'}:
                value = 0.0
            elif prev in {'the', 'a', 'each', 'more', 'hard', 'flight', 'transit'}:
                value = 0.23
        elif word == 'last':
            value = 0.23
            if prev == 'this':
                value = 0.86
            elif prev == 'that':
                value = 0.55
            elif prev in POSSESSIVES:
                value = 0.76
            elif prev in {'can', 'will', 'would', 'could', 'may', 'to', 'call'}:
                value = 0.0
        elif word == 'un':
            value = -0.08
            if it > max(es, fr) + 0.4:
                value = -0.70
            elif es > fr + 0.4:
                value = -0.36
        elif word == 'of':
            if prev in PHOTOGRAPHS:
                value = 0.70
            elif prev in EVIDENCE:
                value = 0.40
            elif prev in {'essence', 'core', 'foundation', 'foundations'}:
                value = -0.50
            elif prev in {'words', 'works'}:
                value = -0.70
        elif word == 'value':
            value = 0.11
            if prev == 'critical':
                value = 1.10
            elif prev == 'this':
                value = 0.42
            elif prev == 'excellent':
                value = 0.80
            elif prev in {'good', 'great'}:
                value = 0.40
        elif word == 'range':
            value = 0.12
            if prev in {'wide', 'broad'}:
                value = 0.62
            elif prev in {'the', 'a', 'this'}:
                value = 0.28
        elif word == 'set' and prev == 'data':
            value = 0.60
        elif word == 'choice':
            value = 0.10
            if prev in {'good', 'better', 'best', 'great', 'excellent'}:
                value = 0.55
        elif word == 'public':
            value = -0.07
            if prev in {'a', 'the', 'in'}:
                value = -0.43
            elif prev in {'general', 'went'}:
                value = -0.95
        elif word == 'the' and prev == 'given':
            value = 0.50
        elif word == 'far' and prev == 'this':
            value = 0.55
        elif word == 'by' and prev in {'edited', 'published', 'posted'}:
            value = 0.30
            if previous == 'Published' or (prev == 'edited' and before == 'last'):
                value = 0.70
        elif word == 'published' and prev in {'first', 'originally'}:
            value = 0.45
    # An Italian article at a sentence boundary, or the ending of 'alcun'.
    elif it > max(es, fr) + 0.4:
        if raw == 'un' and prev == 'alc':
            value = -0.55
        elif raw == 'Un' and (not previous or previous[-1:] in '.!?'):
            value = -0.55
    it = 0.985 * it + (word in ITALIAN)
    es = 0.985 * es + (word in SPANISH)
    fr = 0.985 * fr + (word in FRENCH)
    return (doc, raw, previous, it, es, fr), value

"""Negative response at the beginning of a document or initial repeated-token run.

Its size is estimated from typography and word familiarity. Common function
words and source-file directives receive a weaker response than word fragments.
After a different token provides context, predict zero. This deliberately leaves
out the small context-dependent activations elsewhere in the document.
"""
import math
import unicodedata
from functools import lru_cache
import regex
from wordfreq import zipf_frequency

READS = ()
PRONOUNS = set('i we you he she it they me us him her them my your his its '
               'our their mine yours hers ours theirs'.split())
AUXILIARIES = set('be am is are was were been being have has had do does did '
                  'will would shall should can could may might must'.split())
DIRECTIVES = set('import package using namespace from #include'.split())


@lru_cache(maxsize=8192)
def onset(s):
    z = s.strip()
    if s.startswith('<|') and s.endswith('|>'):
        return -9.4
    if not z:
        if '\t' in s:
            return -8.4
        if s == ' ':
            return -2.6
        if s == '\n':
            return -5.4
        if s.count('\n') >= 2:
            return -3.0
        return -4.2
    if z.isdecimal():
        d = int(z) if len(z) == 1 else 5
        return -4.84 - 0.79*d + 0.03*d*d
    if '\ufffd' in z:
        return -9.9
    if not any(c.isalpha() for c in z):
        value = -4.72 - 1.73*math.log(len(z))
        value -= 1.13 * any(c in '\'"`’' for c in z)
        value += 2.20 * (z in '.,:;!?')
        value -= 1.13 * any(unicodedata.category(c).startswith('S') for c in z)
        value -= 3.0 * any(unicodedata.category(c).startswith('C') for c in z)
        return value - 1.18*s.startswith(' ')
    if regex.search(r'\p{Script=Han}', z):
        return -9.0 + 1.27*math.log(len(z))
    if not regex.search(r'\p{Script=Latin}', z):
        return -9.6
    frequency = zipf_frequency(z, 'en')
    value = -9.90 - 0.69*frequency + 3.01*max(0, frequency-5)
    value += 3.79*s.startswith(' ') + 0.30*z.istitle()
    value -= 0.45*(not z.isalpha())
    value -= 1.93*(z.lower() in PRONOUNS)
    value -= 0.63*(z.lower() in AUXILIARIES)
    value -= 1.45*(len(z) > 1 and len(set(z.lower())) == 1)
    if not s.startswith(' ') and z in DIRECTIVES:
        value += 10.54
    return value


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, token, True)
    elif token != carry[1]:
        carry = (doc, carry[1], False)
    return carry, float(onset(prefix.token_strings[-1]) if carry[2] else 0.0)

"""Approximate an 'ea' spelling response, ignoring case.

The strongest negative response is to 'e' at one token's end followed by
'a' at the next token's start, especially a one-character completion.
Short 'au' completions ('eau' rather than just 'ea') respond more weakly.
Within a token, short, uncommon 'ea' pieces receive larger negative values
than longer pieces. English word frequency measures how uncommon they are.
Other tokens are near zero. The previous token is forgotten at document
boundaries. A conservative scale accounts for variation spelling misses.
"""
from wordfreq import zipf_frequency

READS = ()


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    text = token.lower()
    previous = ''
    if carry is not None and carry[0] == document:
        previous = carry[1]

    if previous.lower().endswith('e') and text.startswith('a'):
        if len(token) == 1:
            value = -3.876
        elif len(previous) > 4:
            value = -0.339
        elif len(token) <= 4:
            value = -0.189 if text.startswith('au') else -1.550
        else:
            value = -0.604
    elif 'ea' in text:
        if len(token) > 4:
            value = -0.144
        elif zipf_frequency(text.strip(), 'en') <= 3.89:
            value = -1.920
        else:
            value = -0.586
    else:
        value = 0.002

    return (document, token), 0.85 * value

"""Detect horizontal padding between fields, not indentation.

Standalone space runs after a word receive a large negative value. Runs after
numbers are weaker; ordinary single spaces, line breaks, and indentation are
mostly quiet. Treat literal escaped newlines like real ones in quoted code.
"""
import re

READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        line, previous = '', ''
    else:
        _, line, previous = carry
    token = prefix.token_strings[-1]
    value = 0.0
    last = line[-1:]
    if token.isspace() and '\n' not in token and '\r' not in token:
        # Whitespace, comment gutters, or a bare line number are not fields.
        indent = not line.strip(' \t#/*|0123456789')
        if '\t' in token:
            if line.strip():
                value = -0.8
                if previous and previous.isspace():
                    value = -2.5
        elif token.strip(' ') == '' and not indent:
            n = len(token)
            if n == 1:
                value = -0.08
                if last in "\"'":
                    value = -0.8
                elif last in ')]}':
                    value = -0.4
            elif last.isalpha() or last in '_/:':
                value = -4.8
                if n == 2:
                    value = -3.8
                if n > 15:
                    value = -3.6
                if n > 32:
                    value = -2.0
            elif last.isdigit():
                value = -1.2
            else:
                value = -1.5
    line = re.split(r'\n|\r|\\n|\\r', line + token)[-1][-256:]
    return (doc, line, token), value

programs.haiku:
"""Enumeration frame detector for layers.1.mlp.down_proj:3338.

What it responds to, in plain words. The component is positive on the word that announces
a list of kinds, ways or items, and negative on quantity phrases and on singular
"a + adjective" phrases.

  + a list noun right after a count or quantity word: "two ways", "three main types",
    "several methods", "the following options", "many reasons"        (strongest, about +1.3)
  + "following" on its own ("the following")                           (about +0.5)
  + a list noun on its own ("ways", "things", "options")               (about +0.1)
  + a count or quantity word ("two", "three", "several", "various")    (about +0.1)
  + "of" after a classifying noun: "types of", "kinds of", "form of"   (about +0.3)
  - "of" after a measure noun: "a bit of", "a lot of", "a summary of"  (about -0.25)
  - an adjective after singular "a": "a short", "a great", "a key"     (about -0.2)
  - runs of middle-dot filler characters "··"                          (about -0.5)

The values are least-squares weights fitted on about 3,000 training rows, so they are in
activation units. The program is a small set of word lists plus additive weights.
"""
READS = ()

COUNT_WORDS = {"two", "three", "four", "five", "several", "various", "many", "few", "both",
               "multiple", "different", "following", "main", "only", "one", "what", "no",
               "types", "kinds", "variety", "sorts"}
ITEM_NOUNS = {"ways", "things", "options", "choices", "choice", "types", "kinds", "methods",
              "reasons", "groups", "categories", "cases", "steps", "sources", "items",
              "elements", "values", "scenarios", "thing", "way", "option", "method", "type",
              "kind", "sorts", "sort", "variety", "factors", "parts", "features"}
CLASS_NOUNS = {"types", "kinds", "kind", "type", "variety", "sort", "sorts", "form", "forms",
               "category", "categories", "part", "piece", "copy", "instance", "instances"}
MEASURE_NOUNS = {"bit", "lot", "amount", "portion", "snippet", "summary", "little", "deal"}
SINGULAR_ADJ = {"short", "great", "sort", "possible", "key", "primary", "large", "final",
                "small", "simple", "good", "correct"}


def _word(s):
    return s.strip().lower()


def step(carry, prefix, upstream):
    cur = _word(prefix.token_strings[-1])
    same_doc = len(prefix) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]
    prev = _word(prefix.token_strings[-2]) if same_doc else ""
    value = 0.0
    if cur and set(cur) == {"·"}:
        value -= 0.5
    if cur in ITEM_NOUNS and prev in COUNT_WORDS:
        value += 1.3
    elif cur in ITEM_NOUNS:
        value += 0.1
    if cur == "following":
        value += 0.5
    if cur == "of" and prev in CLASS_NOUNS:
        value += 0.3
    if cur == "of" and prev in MEASURE_NOUNS:
        value -= 0.25
    if prev == "a" and cur in SINGULAR_ADJ:
        value -= 0.2
    if prev in COUNT_WORDS:
        value += 0.1
    return carry, value

programs.sol:
"""Auxiliary complements, with a few spelling-based side responses.

Be/been/being and past copulas followed by 'able' fire strongly; 'possible',
'interested' and 'willing' are weaker. Modal verbs change these strengths.
Adverbs after be/been tend negative. Smaller rules cover discovery passives,
modal desire/need continuations, 'no/any/some way', and Unix binary directories.
Spelling rules cover be- vowel continuations (with two prefix exceptions),
Germanic consonant continuations, and web compounds/identifiers.

This omits rarer lexical collocations and exceptions. Keep two previous tokens,
resetting at document boundaries; everything unrecognized predicts zero.
"""
READS = ()
ABILITY = {'be': 7.5, 'been': 8.4, 'being': 6.8, 'was': 5.5, 'were': 4.4}
COPULAS = set(ABILITY) | {'is', 'are', 'am', "'s", '’s'}
INSERTIONS = {'also', 'actually', 'eventually', 'then', 'not', 'now'}
ADVERBS = {
    'just', 'still', 'also', 'even', 'then', 'first', 'both', 'not',
    'further', 'here', 'there', 'likely', 'well', 'long', 'often',
}
DISCOVERY = {'found', 'seen', 'observed', 'shown', 'reported', 'noted', 'known'}


def predict(token, p='', q=''):
    w, p, q = (x.strip().lower() for x in (token, p, q))
    tail = w[3:] if w.startswith('web') else ''
    if p.endswith('web'): tail = w
    if tail:
        if tail in {'kit', 'ster', 'ber'}: return -8.0
        if tail.startswith('engine'): return -6.0
        if tail == 'er': return -1.8
        if tail.startswith(('server', 'browser', 'rtc', 'filter')) or tail == '3':
            return -3.0
        if tail == 'mail': return 3.0
        if tail in {'service', 'services'}: return 1.4
    if w in {'/bin', '/sbin'}: return 1.4
    if not token[:1].isspace():
        if p.endswith('be') and w.isalpha():
            if w.startswith(('av', 'gei')): return -2.8
            if w[0] in 'iou': return 3.5
            if w[0] in 'ae': return 1.3
        if w in {'ber', 'ner', 'ste', 'sten', 'ster'}:
            if p.endswith(('eb', 'üb', 'ieb', 'lb', 'we')): return -3.5
        if w.startswith(('ck', 'beck')) and p.endswith(('ä', 'ö', 'ie')):
            return -3.5
        return 0.0
    if w in {'able', 'unable'}:
        a = ABILITY.get(p, 0.25)
        if p == 'be':
            if q in {'should', 'might', 'may'}: a = 10.2
            elif q == 'would': a = 5.0
            elif q in {'can', 'could'}: a = 2.2
        if p in INSERTIONS and q in ABILITY:
            scale = 0.2 if p == 'not' else 0.7
            if p in {'eventually', 'then'}: scale = 1.2
            a = scale * ABILITY[q]
