def normalize_digits(text):
    """Treat subscript, superscript, and fullwidth digits as digits too."""
    out = []
    for ch in text:
        try:
            out.append(str(unicodedata.digit(ch)))
        except (TypeError, ValueError):
            out.append(ch)
    return ''.join(out)


def number_response(run):
    d = int(run[-1])
    n = len(run)
    if d == 0:
        return -0.6 if n == 1 else -0.04
