    group = 0 if d <= 2 else 1 if d == 3 else 2 if d == 4 else 3
    strength = (3.1, 1.5, 1.2, 0.9)[group]
    if n > 1:
        strength -= (1.6, 0.7, 0.5, 0.38)[group]
        if run[-2] == '1':
            strength -= (1.3, 0.5, 0.4, 0.2)[group]
        elif run[-2] == '0':
            strength += (0.8, 0.27, 0.2, -0.06)[group]
        if n > 3:
            strength -= (0.35, 0.05, 0.15, 0.18)[group]
