    doc = prefix.document_ids[-1]
    tail = '' if carry is None or carry[0] != doc else carry[1]
    token = normalize_digits(prefix.token_strings[-1])
    value = 0.0
    if token == '1':
        match = re.search(r'[0-9]+$', tail)
        if match:
            value = number_response(match[0])
        else:
            # Decimal fractions, version numbers, and short numeric separators.
            match = re.search(r'([0-9])([., _+\-])$', tail)
            if match:
                digit, separator = match.groups()
                small = digit in '12'
                if separator == '.':
                    value = 1.07 if small else 0.4 if digit != '0' else 0.0
                elif separator in ',_':
                    value = 0.55 if small else 0.14 if digit != '0' else 0.0
                elif separator in ' +':
                    value = 0.43 if small else 0.08 if digit != '0' else 0.0
                else:
                    value = 0.2 if small else 0.04 if digit != '0' else 0.0
