"""layers.1.mlp.down_proj:3344 - the English particle "up".

This component turns negative on the word "up" when it is a verb particle
("break up", "build up", "tear up", "blow him up", "match up") and on compounds
built on it ("backup", "lookup", "cleanup", "startup", "hookup"; "setup" is
weaker). It is most negative right after an object pronoun ("blow him up",
"break it up"), and weakest in idioms like "end up", "show up", "grew up",
"come up", where "up" barely registers. An unspaced "up" is about half as
strong. It also leaks onto the determiner right after a particle "up"
("take up the slack", "fire up a"), which is still negative there. Every other
token is about zero.

The program reads only the current token and the one before it.
"""

READS = ()

PARTICLE = {"up", "ups"}
COMPOUND = {
    "backup", "startup", "lookup", "cleanup", "hookup", "breakup", "popup",
    "markup", "makeup", "lineup", "pickup", "signup", "buildup", "checkup",
    "wakeup", "keyup",
}
OBJECT_PRONOUN = {"him", "her", "it", "them", "me", "us", "you", "this", "that"}
WEAK_LEAD = {"end", "ended", "ends", "show", "showed", "shows", "grew", "grow",
             "grown", "woke", "wake", "come", "came"}
DETERMINER = {"the", "a", "an", "his", "her", "their", "its", "your"}


def step(carry, prefix, upstream):
    text = prefix.token_strings[-1]
    word = text.strip(" -_./(\t").lower()
    before = ""
    if len(prefix.token_strings) > 1:
        before = prefix.token_strings[-2].strip().lower()
    if before == "up" and word in DETERMINER:
        return carry, -2.0
    if word == "setup":
        return carry, -1.7
    if word in COMPOUND:
        return carry, -3.5
    if word not in PARTICLE:
        return carry, 0.0
    if before in OBJECT_PRONOUN:
        value = -5.0
    elif before in WEAK_LEAD:
        value = -1.0
    else:
        value = -3.5
    if text[:1] not in " -":
        value /= 2
    return carry, value

