PREPOSITIONS = set('''
in on at to from for by with into onto under over between within without
before after during through throughout across around along behind against
about near beside beyond beneath upon towards toward inside outside
'''.split())
COPULAS = set('is are was were be been being'.split())
CONJUNCTIONS = set('''
and or but if when while because although though whether so then
'''.split())
GERMAN_ARTICLES = {
    'die': 1.15, 'der': 0.85, 'das': 0.73,
    'den': 0.68, 'dem': 0.58, 'des': 0.40,
}
ROMANCE_ARTICLES = set('le la les el los las il lo gli'.split())


def english_article(text, previous):
