            return 1.22 if '\n' in previous else 1.55
        if previous.isspace():
            return 1.05 if '\n' in previous else 1.40
        if end.endswith(':'):
            return 0.65
        if end.endswith(('"', "'", '`')):
            return 0.65 if text.startswith(' ') else 0.20
        if end.endswith(('(', '[')):
            return 0.75 if text.startswith(' ') else 0.0
        if end.endswith(','):
            return -0.10 if text.startswith(' ') else 0.50
        if '\n' in previous:
            return 0.60
        if text.startswith(' ') and previous[-1:].isalpha():
            return 0.0
        return 0.45

    if word in PREPOSITIONS:
        return 1.71
    if word == 'of':
        return 1.37
    if word in COPULAS:
        return 0.81
    if word == 'that':
        return 1.56
    if word == 'all':
        return 0.22
    if word in CONJUNCTIONS:
        return 1.22
    if end.endswith(('(', '[', '"', '`')):
        return 0.29
    if end.endswith(':'):
        return 0.61
    if end.endswith(','):
        return 1.23
    if end.endswith(('.', '!', '?')):
        return 0.75
    if word.isdigit():
        return 0.30
    if previous.strip().istitle():
        return 0.94
    parts = wordnet.parts_of_speech(word)
    if parts == {'verb'}:
        return 1.52
    if 'noun' in parts and not parts.intersection({'verb', 'adverb'}):
        return 0.67
    if parts == {'adverb'}:
        return 1.08
    return 1.25


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    text = prefix.token_strings[-1]
    word = text.strip().lower()
    first = carry is None or carry[0] != doc
    position = 0 if first else carry[1] + 1
    state = (doc, position)
    previous = '' if first else prefix.token_strings[-2]

    if first:
        if word == 'the':
            return state, -1.25 if text == 'The' else -0.60
        if text.startswith('<|'):
            return state, -0.55
        return state, -0.47 if any(c.isalpha() for c in text) else -0.21

    if text == ':' and position == 1 and previous == 'Title':
        return state, 25.87
    if word == 'the':
        return state, english_article(text, previous)
