    'nasal_cluster': -3.6,
    'rare_cluster': -3.7,
    'other_cluster': -0.4,
    'function_abbreviation': -2.3,
    'fin_syllable': -2.5,
    'fun_syllable': -2.2,
    'word_fun': -0.7,
    'nonnasal_syllable': 0.9,
    'fant_syllable': 1.2,
    'open_fu': 0.8,
    'attached_f': 0.2,
    'arabic_f': 0.6,
    'split_nasal_cluster': -5.4,
    'split_rare_cluster': -6.7,
    'split_other_cluster': -1.3,
    'split_function_abbreviation': -1.2,
    'split_fin_syllable': -4.6,
    'split_fun_syllable': -3.6,
    'split_nonnasal_syllable': 1.1,
    'split_fant_syllable': 1.2,
    'split_open_fu': 0.9,
