import re

READS = ()


def estimate(s, before):
    word = s.strip(' \t\r\n._=(')
    lower = word.lower()
    b = before.rstrip()
    if lower in ('exp', 'expr') and re.search(r'reg$', b, re.I):
        return -14.5  # fragmented regexp
    if lower in ('expression', 'expressions', 'matching') and re.search(
        r'(?:regular|regex|regular expression)$', b, re.I
    ):
        return -8.5  # regular expression
    if s == 'attern' and b.endswith('P'):
        return -6.5  # completing a split Pattern name
    if s == '则' and b.endswith('正'):
        return -9.8  # chinese regex
    if s == '表达' and b.endswith('正则'):
        return -4.8  # chinese expression
    if lower in ('regex', 'regexp'):
        return -6.3  # regex word
    if word == 're':
        if re.search(r'(?:import|from)\s*$', b):
            return -8.5  # import re
        if re.search(r'(?:[=,(]|\b(?:if|in|not|return))\s*$', b):
            return -1.6  # re identifier
    if b.endswith('re') and s.startswith('.') and word in (
        'MULT', 'MULTILINE', 'IGNORECASE', 'DOTALL', 'VERBOSE'
    ):
        return -6.0  # Python regex flags
    if s.startswith('.') and lower in (
        'sub', 'subn', 'compile', 'match', 'fullmatch', 'search',
        'findall', 'finditer', 'split', 'matcher'
    ):
        if (re.search(r'\bre$', b) or
            (lower == 'compile' and re.search(r'\bPattern$', b))) and word == lower:
            return -13.9  # regex method
        if re.search(r'(?:regex|regexp|pattern|_re)$', b, re.I):
            return -6.7  # pattern method
    if lower == 'replace' and re.search(r'preg$', b):
        return -17.2  # preg replace
    if lower == 'rep' and re.search(r'(?:pg|g)$', b):
        return -2.9  # fragmented grep
    if lower == 'grep':
        return -4.7  # grep
    if word == 'sed':
        return -0.5 if s.startswith(' ') else -3.1
    if s == 's' and re.search(r'\bsed\b[^\n;]{0,20}[\'\"]$', b):
        return -8.4  # sed substitution
    if s.startswith('/') and re.search(r'\bsed\b[^\n;]{0,24}[\'\"]s$', b):
        return -5.5  # sed separator
    if lower in ('replaceall', 'replacefirst'):
        return -8.3  # regex replacement
    if lower in ('pattern', 'patterns', 'matcher'):
        if s.startswith(' ') and not re.search(r'(?:regex|regular expression)$', b, re.I):
            return -0.4  # pattern prose
        return -3.2  # pattern name
    if word in ('split', 'rsplit', 'Split'):
        return -3.1 if not s.startswith(' ') else 0.0
    if word == 'replace':
        if s.startswith('_'):
            return -5.8  # replace tool
        return -0.2 if s.startswith(' ') else -2.2
    if word == 'join':
        if s.startswith(' '):
            return 0.0  # background
        return -0.4 if s.startswith('.') else -1.0
    if lower in ('match', 'matches', 'matching'):
        return -0.2 if s.startswith(' ') else -1.3
    if word in ('contains', 'includes', 'find') and not s.startswith(' '):
        return -0.8  # substring test
    if lower in ('scanf', 'sscanf', 'fscanf', 'fopen', 'explode', 'implode', 'substr'):
        return -0.6  # string io
    if s == '匹配':
        return -0.5  # chinese match

    # Starts of regex arguments and command-line pattern arguments.
    if re.search(r'\b(?:grep|sed)\b(?:\s+-[\w]+)*\s*$', b):
        if s.strip() == '-':
            return -2.0  # pattern flag
        if s.strip(' \\') in ('"', "'"):
            return -0.3 if '\\' in s else -5.5
    regex_call = re.search(
        r'(?:\.(?:compile|sub|subn|search|findall|finditer|match|fullmatch|'
        r'replaceAll|replaceFirst)|preg_\w+)\s*\(?$', b
    )
    if regex_call and re.search(r'[\'\"\[\\]', s) and len(s) < 7:
        if '/' in s and re.search(r'preg_\w+', b):
            return -13.9  # preg regex literal
        return -6.1 if '[' in s else -3.2
    if (re.search(r'\.(?:join|replace|split)\s*$', b)
            and s.startswith(('(\"', "('", '(\\'))):
        return -2.0  # string argument
    if '/' in s and '^' in s and len(s) < 8:
        return -14.1  # anchored regex literal
    if s.lstrip().startswith('(/'):
        return -14.9 if re.search(r'(?:match|replace|split|\bif)$', b) else 0.0
    if s in (' /', '/', ' /\\') and b.endswith((',', '=', '&&', '||', 'return')):
        return -3.4  # slash literal
    if s == "'\\" and b.endswith('r'):
        return -5.0  # backslash beginning a raw string

    # Familiar pieces of regular-expression syntax.
    if s == '-Z' and b.endswith('A'):
        return -9.7  # uppercase range
    if s.startswith('(?') and s[2:3] in (':', '=', '!'):
        return -9.5  # regex group
    if s.startswith('.*'):
        if re.search(r'(?:\.(?:compile|sub|match)|grep)[^;\n]{0,70}$', b):
            return -5.0  # regex wildcard
        return -0.3  # wildcard quantifier
    if s in (']+', ']*', ']+)', ']*)'):
        return -2.3  # class quantifier
    if s == '[^':
        return -3.4  # class negation
    if s.startswith('*.' ):
        return -1.0  # file glob
    if '^' in s and len(s.strip(' \\\"\'^(')) == 0 and ('\"' in s or "'" in s):
        return -4.6  # quoted anchor
    if s.startswith('^') or s.strip() == '^':
        if b.endswith(('"', "'", '[', '`')):
            return -4.2  # regex anchor
    return 0.0  # background


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    before = carry[1] if carry is not None and carry[0] == doc else ''
