    value = estimate(s, before)
    return (doc, (before + s)[-128:]), float(value)

"""A short-subword u/o detector, with zero and metadata-format responses.

A token ending in u followed by a token beginning in o is positive;
accents count as the same vowel, but token endings qu are excluded.
Longer pieces weaken the response. A token consisting only of uo
also gets a smaller response. Repeated zeroes are usually negative,
except for the second zero after u/U. Finally, two metadata labels
and document-opening Java/Python declarations have explicit rules.
These rules approximate the main spikes, not all lexical variation.
"""
import unicodedata

READS = ()


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    if carry is None or carry[0] != document:
        previous, tail, position = '', '', 0
    else:
        _, previous, tail, position = carry
    token = prefix.token_strings[-1]
    plain = ''.join(c for c in unicodedata.normalize('NFD', token)
                    if not unicodedata.combining(c))
    value = 1.0 if plain.lower() == 'uo' else 0.0

    if previous.lower().endswith('u') and plain.lower().startswith('o'):
        if not previous.lower().endswith('qu'):
            extra = max(0, len(previous.strip()) - 2) + max(0, len(token) - 3)
            value = (2.5 if plain != token else 2.1) * 0.55 ** extra

    if token == '0':
        if previous.lower().endswith('u'):
            value = 0.6
        elif previous == '0':
            value = -0.15
            if tail.endswith('U0'):
                value = 7.2
            elif tail.endswith('u0'):
                value = 4.3
            elif tail.endswith(',0'):
                value = -0.30
            elif tail.endswith(':0'):
                value = -0.21

    if previous == 'Joined' and token == ':':
        value = 0.9
    if position == 1 and previous == 'Title' and token == ':':
        value = -5.8
    if position == 0:
        if token == 'package':
            value = 2.6
        elif token == 'from':
            value = 1.65
    return (document, token, (tail + token)[-2:], position + 1), value

"""Approximate a Ukrainian spelling signal, dominated by separately tokenized і.

The negative response is strongest after a consonant-only word prefix and
weakens after earlier vowels. Cyrillic-word apostrophes also respond strongly.
An echo lasts into the next two Cyrillic letter tokens, especially voiceless
sibilants and the palatalized lateral ль. Other tokens are near zero, apart
from a small document-start baseline. Only 128 recent bytes are remembered.
"""
import re
import unicodedata

READS = ()
VOWELS = frozenset('аеєиіїоуюяАЕЄИІЇОУЮЯ')
VOICELESS_SIBILANTS = frozenset('сшчщ')
WORD_END = re.compile(r'[^\W\d_]*$')


def cyrillic_letters(text):
    return text.isalpha() and all(
        'CYRILLIC' in unicodedata.name(c, '') for c in text
    )


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    first = carry is None or carry[0] != doc
    if first:
        tail, echo, age = b'', 0.0, 0
    else:
        _, tail, echo, age = carry
    token = prefix.token_strings[-1]
    value = -0.2 if first else 0.0

    if token in ('і', "'", '’'):
        before = WORD_END.search(tail.decode('utf-8', 'ignore'))[0]
        vowels = sum(c in VOWELS for c in before)
        if token == 'і':
            value = (-8.1, -3.9, -2.1, -1.5)[min(vowels, 3)]
            if not before:
                value = -0.8
        elif cyrillic_letters(before):
            value = -5.4 if vowels else -8.5
        echo, age = value, 0
    elif token in (' і', 'І'):
        value = -1.4 if token == ' і' else -3.3
        echo, age = 0.0, 0
    elif echo and cyrillic_letters(token):
        age += 1
        if age == 1:
            rate = 0.4
            if token == 'ль' or token in VOICELESS_SIBILANTS:
                rate = 0.9
            elif token[0] in VOWELS:
                rate = 0.1
        elif age == 2:
            rate = 0.3 if token in VOICELESS_SIBILANTS else 0.1
            if token[0] in VOWELS:
                rate = 0.02
        else:
            rate, echo = 0.0, 0.0
        value = echo * rate
    else:
        echo = 0.0

    tail = (tail + prefix.token_bytes[-1])[-128:]
    return (doc, tail, echo, age), float(value)

programs.haiku:
"""Ukrainian syllable-onset detector: the letter і, and the consonant after it.

Layer 1, MLP unit 3354 (down_proj) goes strongly negative on the Ukrainian
letter і (U+0456, which Russian does not use) when it sits early in its word,
right after a vowel-free consonant start: в|і|йна, від, зд|і|йснити, д|і|ї,
м|і|ста, п|і|дприємство, к|і|лька. There the activation is around -8 to -11.
Later і's (after a vowel, as in реа|л|і|зація, терм|і|нологія, Харк|і|в)
are much weaker, about -3, and sometimes slightly positive.

The consonant that follows such an і (the д in від, the ль in кількість,
the с in місія) is also negative, around -2.5. Vowels after і are only
slightly negative and everything else is near zero, so the program predicts 0
there. Russian text, with no і, stays near zero throughout.

The program keeps no state between positions: it reads the newest token and
scans back over the tokens of its own word (no earlier words, no earlier
document) to see whether a vowel came first.
"""

READS = ()

# Cyrillic vowel letters (Ukrainian, Russian and Belarusian).
VOWELS = set("аеёиіїоуюяєыэ")


def _cyrillic(text):
    """True if text is non-empty and made only of Cyrillic letters."""
    return bool(text) and all("Ѐ" <= c <= "ӿ" for c in text)


def _word_before(prefix, end):
    """Cyrillic letters of the word that token `end` (exclusive) belongs to."""
    parts = []
    for j in range(end - 1, -1, -1):
        if prefix.document_ids[j] != prefix.document_ids[end]:
            break
        s = prefix.token_strings[j]
        if not _cyrillic(s.strip()):
            break
        parts.append(s.strip())
        if s[:1] == " ":  # a leading space marks the start of a word
            break
    return "".join(reversed(parts))


def step(carry, prefix, upstream):
    raw = prefix.token_strings[-1]
    token = raw.strip()
    n = len(prefix)
    if raw == " і":
        return None, -1.0  # the standalone word і ("and")
    if raw == "і":
        before = _word_before(prefix, n - 1)
        if any(c in VOWELS for c in before):
            return None, -3.1  # і later in a word, after a vowel
        return None, -8.5  # і right after a vowel-free consonant start
    if n > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]:
        if "і" in prefix.token_strings[-2] and _cyrillic(token):
            if not any(c in VOWELS for c in token):
                return None, -2.5  # consonant right after an і
    return None, 0.0

programs.sol:
"""A lexical pulse at the beginning of each document.

The response is strongest for certain introductory function words and person
roles/titles. Other opening tokens receive a small adjustment for their form
and dictionary word classes. After the opening token the prediction is zero.
This approximates the opening pulse, not all token-specific variation.
"""
import wordnet

READS = ()
HONORIFICS = {
    'mr', 'mrs', 'ms', 'dr', 'sir', 'lady', 'lord', 'professor',
    'president', 'captain', 'king', 'queen',
}
SPEAKING_ROLES = {'user', 'assistant', 'speaker', 'presenter'}


def opening(text):
    s = text.strip()
    w = s.lower()
    spaced = text.startswith(' ')
    if w == 'by':
        return (13.1 if spaced else 21.9) if s.istitle() else (
            10.6 if spaced else 17.6)
    if w == 'if':
        return (9.3 if spaced else 13.7) if s.istitle() else (
            4.6 if spaced else 3.2)
    if w in {'before', 'after'}:
        return 7.5
    if w == 'but':
        return 5.0
    if w == 'my':
        return 3.8 if spaced else 8.0
    if w in HONORIFICS:
        return 8.5
    if w in SPEAKING_ROLES:
        return 8.0
    if s.startswith('<|') and s.endswith('|>'):
        return 0.3

    pos = wordnet.parts_of_speech(s)
    cats = wordnet.categories(s)
    if s.istitle() and 'noun.person' in cats:
        return 2.5 if spaced else 4.0
    value = -0.15 - 0.18 * spaced + 0.5 * s.istitle()
    value += 0.33 * (len(s) >= 4) - 0.6 * ('\n' in text)
    value -= 0.3 * s.isdigit() + 0.33 * (w in {'a', 'an', 'the'})
    value += 0.33 * ('verb' in pos) + 0.54 * ('adjective' in pos)
    value += 0.24 * ('adverb' in pos)
    if cats == {'noun.person'}:
        value += 1.2
    elif 'noun.person' in cats:
        value -= 0.33
    elif 'noun' in pos:
        value -= 0.46
    return value


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    first = carry is None or carry != doc
    return doc, opening(prefix.token_strings[-1]) if first else 0.0

"""Approximate activation from document-opening typography and spelling.

Opening whitespace, quotation marks and line endings tend to be positive;
opening words tend to be negative, especially uncommon title-case fragments.
The estimate persists through an opening run of identical tokens. These are
coarse spelling/format classes, not a table of learned token identities.
Small context-dependent fluctuations after the opening are omitted.
"""
from functools import lru_cache

import regex
from wordfreq import zipf_frequency

READS = ()


@lru_cache(maxsize=8192)
def opening_value(token):
    text = token.strip()
    letters = any(c.isalpha() for c in text)
    if token.startswith('<|'):
        return 0.08
    if not letters:
        if token.count(' ') >= 2:
            return 1.71
        if '\n' in token:
            if token.count('\n') == 1:
                return 1.38 if token == '\n' else 1.15
            return 0.55
        if any(c in text for c in '\'"“”‘’'):
            return 1.30 if all(c in '\'"“”‘’' for c in text) else 0.45
        if text.isascii() and text.isdigit():
            return 0.16 if int(text) <= 3 else -0.20
        return 0.09

    if not text.isascii():
        for script, value in [('Han', -0.53), ('Hiragana', 0.17),
                              ('Katakana', 0.17), ('Cyrillic', -0.17),
                              ('Arabic', 0.43)]:
            if regex.search(r'\p{Script=' + script + '}', text):
                return value
        return -0.29

    frequency = zipf_frequency(text, 'en')
    if text.lower() in {'this', 'that', 'these', 'those'}:
        return -0.09
    if text.istitle():
        if text.isupper():
            return -0.69 if frequency < 6 else 0.16
        return -1.18 if frequency < 6 else -0.63
    if '_' in text:
        return 0.005
    if frequency > 7.1:
        return -0.16 if text.lower() in {'of', 'to', 'in', 'for', 'on',
                                       'with', 'at', 'from', 'by', 'as'} else 0.11
    return -0.54


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    token_id = prefix.token_ids[-1]
    if carry is None or carry[0] != document:
        value = opening_value(prefix.token_strings[-1])
        return (document, token_id, True, value), value
    document, first, repeating, value = carry
    repeating = repeating and token_id == first
    return (document, first, repeating, value), value if repeating else -0.0072

"""A quotation-boundary detector, strongest at the next key of a mapping.

A small delimiter stack distinguishes {...} from lists and function arguments.
Quotes after a short, quoted mapping value get the largest negative response;
long values and intervening line breaks weaken it. This is only a punctuation
heuristic, not a JSON parser: brackets in displayed/escaped code count too.
The assistant role label has a separate positive response. There is also a
positive baseline at the beginning of a document.
"""
import math
import re

READS = ()
CLOSERS = {'}': '{', ']': '[', ')': '('}
ESCAPED_SPACE = re.compile(r'\\+([nrt])')


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    fresh = carry is None or carry[0] != doc
    if fresh:
        stack, tail, colon_age, brace_age = [], '', 1000, 1000
    else:
        _, stack, tail, colon_age, brace_age = carry

    token = prefix.token_strings[-1]
    value = 0.17 if fresh else 0.001
    if token == '<|im_start|>':
        value = 0.037
    elif token == 'assistant' and tail.endswith('<|im_start|>'):
        value = 0.385
    elif token in ('<tool_call>', '<tool_response>'):
        value = 0.052
    elif token == ' {"':
        value = -0.16
    elif not fresh:
        quote = token.strip().replace('\\', '')
        if quote in ('"', "'"):
            context = ESCAPED_SPACE.sub(
                lambda m: {'n': '\n', 'r': '\r', 't': '\t'}[m[1]], tail)
            context = context.replace('\\', '')
            trimmed = context.rstrip()
            gap = len(context) - len(trimmed)
            last = trimmed[-1:]
            quoted_comma = trimmed.endswith(('",', "',"))
            top = stack[-1] if stack else ''
            value = 0.07 if '\\' in token else 0.02
            if last == ',':
                if quoted_comma and top == '{':
                    # The key signal fades as the preceding value gets longer.
                    strength = 0.6 + 1.4 * math.exp(
                        -0.06 * max(0, colon_age - 3))
                    if '\n' in context[len(trimmed):]:
                        strength *= 0.65
                    value = -strength
                elif quoted_comma:
                    value = -0.6 if quote == "'" and top != '(' else -0.1
                elif top == '{':
                    value = -1.3
                elif gap > 3:
                    value = -1.15
                else:
                    value = -0.09
            elif last == '{':
                value = -1.1
            elif gap > 3:
                value = -0.85 if brace_age <= 6 else -0.23

    # Keep local syntax, even when it appears inside quoted command text.
    for char in token:
        if char in '{[(':
            stack.append(char)
        elif char in CLOSERS and CLOSERS[char] in stack:
            while stack.pop() != CLOSERS[char]:
                pass
    colon_age = 0 if ':' in token else colon_age + 1
    brace_age = 0 if '{' in token else brace_age + 1
    tail = (tail + token)[-300:]
    return (doc, stack, tail, colon_age, brace_age), value

programs.haiku:
"""Location-phrase feature (layer 1, MLP down_proj, component 3359).

Fires on two-word location phrases and on the word that follows a location word.
- Positive on the second word of a compass or position compound: top LEFT,
  bottom RIGHT, North EAST, south WEST, lower-DIMENSIONAL.
- Negative on a noun that names a part, side or surface of something, when a
  location word comes just before it: the top HALF, bottom EDGE, upper WALL,
  southeastern PART, upper PANEL, western PORTION, side VIEW. Chinese 西北部,
  内側 and 外側 behave the same way.
- Negative on 'of' after such a noun (upper part OF), and on 'of' after a
  time-span noun (the first nine months OF, the last day OF).
- Slightly negative on the first token of each document.
Everything else is about zero.
"""
READS = ()

LOCATION = {"top", "bottom", "upper", "lower", "higher", "north", "south", "left", "right", "east", "west",
            "northern", "southern", "eastern", "western", "northeastern", "northwestern",
            "southeastern", "southwestern", "central", "middle", "front", "back", "rear", "inner",
            "outer", "anterior", "posterior", "basal", "hind", "side", "far", "most",
            "上", "下", "内", "外", "东", "西", "南", "北", "顶", "底", "左", "右", "前", "后", "中", "西北", "东南"}
COMPASS_2 = {"left", "right", "east", "west", "north", "south", "bottom", "top", "dimensional", "dimension", "order"}
ORDINAL = {"first", "second", "third", "last", "earliest", "latest", "final"}
STRONG = {"part", "parts", "half", "portion", "portions", "panel", "edge", "edges", "wall", "surface",
          "face", "view", "views", "板", "部", "半"}
MEDIUM = {"side", "sides", "end", "ends", "section", "region", "regions", "area", "point", "bank", "bound",
          "limit", "row", "margin", "layer", "boundary", "border", "base", "roof", "frame", "plate", "plates",
          "board", "corner", "wing", "tips", "tip", "width", "quarter", "electrode", "diameter", "lob", "sheet",
          "window", "側", "侧", "面", "楼", "段", "郊", "層", "角"}
PART_NOUN = STRONG | MEDIUM
SPAN = {"day", "days", "month", "months", "year", "years", "stage", "phase"}


def word(s):
    return s.strip().lstrip("-").lower()


def step(carry, prefix, upstream):
    cur = word(prefix.token_strings[-1])
    if len(prefix) == 1 or prefix.document_ids[-1] != prefix.document_ids[-2]:
        return carry, -0.25
    prev = word(prefix.token_strings[-2])
    prev2 = word(prefix.token_strings[-3]) if len(prefix) > 2 else ""
    if cur in COMPASS_2 and prev in LOCATION:
        return carry, 3.5
    if cur in STRONG and prev in LOCATION:
        return carry, -5.0
    if cur in MEDIUM and prev in LOCATION:
        return carry, -2.5
    if cur == "of":
        if prev in PART_NOUN and prev2 in LOCATION:
            return carry, -3.0
        if prev in SPAN and (prev2 in ORDINAL or prev2 in LOCATION):
            return carry, -3.0
        if prev in SPAN:
            return carry, -1.0
    return carry, 0.0

programs.sol:
"""Sparse spelling and encoding cues, not a single semantic category.

Negative cues include Go's 'package main', diaeresis-i outside normal vowel
sequences, and particular split Unicode marks.  Latvian -īgi and Hungarian
accented-vowel continuations are positive.  A few code/markup openers have
large responses at the very start of a document.  URL separators and three
math signs have small offsets.  Everything else is approximately zero; the
weak responses on ordinary text are left unmodeled.
"""

READS = ()

# Values apply when a one-byte continuation finishes the named character.
