   `return`, `break`, `continue`, and the `{` or `):` that opens a block. Everything else is 0.

Predictions are in the component's own units (activation = (x.V)*||U||). Values are fitted
by hand from activations on training rows; no table of token ids is used.
"""

READS = ()

KEY_COLON = {'":', "':", '\\":', '":"', ':"', "':\n", '":\n'}
VALUE_OPENERS = {' =>': 1.3, ' =': 0.4, ' :=': 0.8, ' <-': 0.8}
FLOW = {' return', '\treturn', 'return', ' break', '\tbreak', 'break', ' continue', '\tcontinue'}
BLOCK_OPENERS = {' {\n', '):\n', '){\n', '(){\n'}


def alone_value(tok):
    """Activation of a token that has no context: depends only on what the token is."""
    if '\n' in tok:
        return 3.0
    if tok == ' ':
        return 13.8
    if tok.strip() == '':
        return 8.0
    return {1: 3.5, 2: 2.2, 3: 1.7, 4: 1.0, 5: 0.5}.get(len(tok), 0.3)


def syntax_value(tok, brace_open):
    """Mid-document: how strongly a token opens a value in code."""
    if tok == ':' and brace_open:
        return 0.7
    if tok in KEY_COLON:
        return 1.3
    if tok in VALUE_OPENERS:
        return VALUE_OPENERS[tok]
    if tok in FLOW:
        return 1.1
    if tok in BLOCK_OPENERS:
        return 0.4
    return 0.0


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    new_doc = len(prefix) == 1 or prefix.document_ids[-1] != prefix.document_ids[-2]
    # carry: (previous token, is the document so far one token repeated, is a '{' open on this line)
    if carry is None or new_doc:
        same_run, brace_open = True, False
    else:
        prev, same_run, brace_open = carry
        same_run = same_run and tok == prev
    if '\n' in tok:
        brace_open = False
    value = alone_value(tok) if same_run else syntax_value(tok, brace_open)
    if '{' in tok:
        brace_open = True
    return (tok, same_run, brace_open), value

programs.sol:
"""Local military vocabulary, with spelling-sensitive amplitudes.

Negative responses recognize armed services, their names (Air Force,
Coast Guard), and military stems split across tokens. Chinese army words,
Korean 군 and Vietnamese quân are included. Smaller side responses cover
the honorific 君 and Greek nu followed by omicron/epsilon. Everything else
is zero. Only a short byte suffix is carried, resetting at document changes.
"""
import re
import unicodedata

READS = ()

# Whole-token armed-services vocabulary; capitals sometimes change strength.
MILITARY = {
    'army': -5.6, 'armies': -1.6, 'navy': -7.8,
    'naval': -4.5, 'Naval': -7.2, 'nav': -1.5,
    'military': -2.35, 'milit': -1.35, 'armed': -3.1,
    'defence': -1.4, 'Defence': -3.1,
    'defense': -0.8, 'Defense': -1.7,
}


def predict(raw, history):
    token = raw.decode('utf-8', 'replace')
    before = history.decode('utf-8', 'ignore')
    # Join byte fragments before recognizing an army character.
    if '\ufffd' in token:
        complete = (history + raw).decode('utf-8', 'replace')
        if complete.endswith(('军', '軍', '군')):
            token = complete[-1]
            if token in ('军', '軍'):
                return -14.5
    word = token.strip()
    lower = word.lower()
    stem = before.lower()
    match = re.search(r'([^\W\d_]+)\s*$', stem)
    previous = match[1] if match else ''

    if word in ('军', '軍', '海军', '空军', '解放军'):
        return -9.2
    if word in ('美军', '美軍'):
        return -5.0
    if len(word) > 1 and any(c in word for c in '军軍'):
        return -2.6
    if word == '兵':
        return -1.3
    if word == '警':
        return -0.6
    if word == '君':  # lord/honorific; also pronounced jun, like 军
        return -0.85
    if lower == 'quân':
        return -4.8
    if word == '군':
        return -2.1 if before and before[-1].isalnum() else -8.7

    if token and before.endswith(('ν', 'Ν')):
        vowel = unicodedata.normalize('NFD', token)[0]
        if vowel == 'ο':
            return 2.5
        if vowel == 'ε':
            return 1.65

    if lower in ('force', 'forces'):
        if previous == 'air':
            return -9.9 if lower == 'force' else -3.7
        if previous in ('armed', 'defence', 'defense'):
            return -3.7
        if previous in ('security', 'military', 'imperial', 'frontier', 'joint', 'strike'):
            return -1.7
        return -0.18
    if lower == 'guard':
        return {'coast': -9.4, 'national': -3.9}.get(previous, -0.33)
    if lower == 'corps':
        return -3.4 if previous == 'marine' else -0.3
    if lower in ('defence', 'defense'):
        if previous == 'air':
            return -4.8
        if stem.rstrip().endswith('department of'):
            return -3.8
    if lower in MILITARY:
        # A swarm is not an armed service.
        if lower != 'armed' or not stem.endswith('sw'):
            return MILITARY.get(word, MILITARY[lower])

    # Completion of military stems in English and neighboring languages.
    if not token[:1].isspace():
        if stem.endswith('arm'):
            endings = {
                'ament': -9.0, 'aments': -9.0, 'amento': -6.0,
                'oured': -4.3, 'ored': -4.3,
                'ado': -4.3, 'ados': -5.6, 'ada': -3.0, 'adas': -4.3,
                'ée': -6.0, 'ées': -6.0, 'é': -5.0,
                'ee': -4.0, 'ies': -6.5,
            }
            if lower in endings:
                return endings[lower]
        if lower == 'my' and re.search(r'\bar$', stem):
            return -8.5
        if lower == 'avy' and re.search(r'\bn$', stem):
            return -13.0
        if lower == 'al' and stem.endswith('nav'):
            return -9.5
        if lower == 'ance' and stem.endswith('ordn'):
            return -3.9
        if lower in ('ence', 'ense') and stem.endswith('def'):
            return -3.6
        if lower == 'man' and re.search(r'\bair$', stem):
            return -3.3
    return 0.0


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    history = carry[1] if carry is not None and carry[0] == document else b''
    raw = prefix.token_bytes[-1]
    return (document, (history + raw)[-80:]), predict(raw, history)

"""Approximate a local n-consonant spelling contrast.

Short ENV/NV fragments and n-v continuations are negative; n-f and some
N-initial abbreviations are positive. There are parallel short-fragment
rules for Arabic/Persian, Cyrillic and Japanese n. Unix /usr/bin/env is
especially negative; environment words have weaker software-context rules.
Document starts and paired middle dots have small secondary corrections.
A conservative overall gain moderates unmodeled contextual variation.
Unmatched positions are zero. State resets at each document boundary.
"""
import re

READS = ()
# Familiar N-initial sports and broadcasting abbreviations.
N_INITIALS = {'nba', 'nbc', 'nfl', 'nhl', 'nxt'}
SOFTWARE = re.compile(
    r'\b(code|test\w*|python|import|package|process|shell|variable\w*|'
    r'virtual|docker|server|development|config\w*|function|sys|lib|'
    r'command|runtime|module|npm|pip|software|bash)\b', re.I
)


def response(s, previous, context, first):
    w = s.strip().lower()
    bare = w.lstrip('._/-(')
    p = previous.lower()
    attached = not s[:1].isspace()
    # Short n-combinations in other alphabets: nun, en, and syllabic n.
    if len(w) <= 2 and w.startswith('ند'):  # Arabic/Persian nd
        return 3.2 if previous.endswith('ن') else 1.4
    if len(w) <= 2 and w.startswith('نج'):  # Arabic/Persian nj
        return -1.9
    if len(w) <= 3 and attached and previous.endswith('ن'):
        if w.startswith('د') and context.endswith('نن'):
            return 9.0
        if w.startswith('ب'):
            return 2.4
        persian = any(letter in context for letter in 'پچژگکی')
        if persian and w.startswith(('ه', 'ش')):
            return 2.7
        if w.startswith(('ظ', 'ف')):
            return -1.7
    if attached and p.endswith('н'):
        if len(w) <= 2 and w.startswith('в'):
            return -5.0
        if len(w) <= 3 and w.startswith(('ш', 'л')):
            return 2.0
        if s in ('И', 'О') and previous.isupper():
            return 2.0
    if len(w) == 1 and previous.endswith(('ン', 'ん')):
        if w in ('ビ', 'び'):
            return -5.5 if previous in ('ン', 'ん') else -2.4
        if w in ('コ', 'こ'):
            return -2.4
    if bare == 'env':
        if s == '/env' and p.endswith('bin'):
            return -18.5
        return -6.3
    if bare == 'nv':
        return -4.6 if s.startswith(' ') else -7.5
    if len(bare) <= 4 and bare.startswith('inv'):
        return -2.3
    if len(bare) == 3 and bare.endswith('nv'):
        return -4.5
    if bare.startswith('environment') or bare == 'environ':
        if s[:1].isspace():
            return -1.2 if SOFTWARE.search(context) else 0.0
        return -2.0
    if 'env' in w:
        return -4.8 if len(w) <= 5 else -0.5
    if w in N_INITIALS:
        return 2.8
    if attached and p.endswith('n'):
        if context.endswith('\\n'):
            return 0.0
        if w == 'ft':
            return 8.8 if p.strip(' ./_') == 'n' else 3.6
        if w == 'fl':
            return 5.5 if p.strip(' ./_') == 'n' else 1.5
        if p.strip(' ./_-\t') == 'n':
            if 'n' + w in N_INITIALS:
                return 4.5
            if (s.isupper() and len(w) == 3 and w[0] in 'ei'
                    and all(ch not in 'aeiou' for ch in w[1:])):
                return 1.7
        if w.startswith('v'):
            fragment = p.strip(' ./_-\t')
            if len(w) == 1 and len(fragment) == 2:
                if fragment[-2] in 'bcdfghjklmnpqrstvwxyz':
                    return -11.5
            if p.endswith('en'):
                if len(w) == 1:
                    return -10.0
                if w.startswith('vo') and len(w) <= 3:
                    return -11.5
                if len(w) <= 4:
                    return -5.0
                if w.startswith('viron'):
                    return -3.0
            if p.endswith('in'):
                return -4.0 if len(w) == 1 else -0.8
            if len(w) == 1:
                return -8.0 if previous.isupper() else -5.0
            if len(w) <= 3:
                return -1.0 if w[1:2] == 'a' else -3.5
    # Completions of envoy and envied.
    if p.endswith('env') and w in ('oy', 'ied'):
        return -3.9
    if s == '··':
        return -1.55
    if first and s.strip().isalnum():
        return 1.1 if w in ('import', 'def') else -0.8
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    first = carry is None or carry[0] != doc
    previous, context = ('', '') if first else carry[1:]
    s = prefix.token_strings[-1]
    value = 0.85 * response(s, previous, context, first)
    return (doc, s, (context + s)[-1500:]), value

"""A sparse Vietnamese noun-phrase detector, with a few boundary effects.

Plural determiners and noun classifiers give the strongest negative values.
Other nominal/counting and spatial words give smaller negative values. A
preceding quantifier weakens 'người' (person). In Vietnamese text, selected
consonant onsets and simple toned-vowel fragments give positive
values. Distinctive Vietnamese diacritics establish a language context that
fades over subsequent tokens.

At document start, most negative noun responses weaken; Korean and several English
word/formatting classes receive coarse offsets. A leading run of doubled
middle dots is also recognized. Everything else is predicted zero. This is
a sparse approximation, not an account of the many smaller responses.
"""
import re
import unicodedata

READS = ()

PLURALS = {'các', 'những'}
CLASSIFIERS = {'con', 'cái', 'cuộc', 'chiếc'}
# Nominal heads used for counting events, pieces, pairs, people, and categories.
NOMINALS = {'việc', 'cặp', 'câu', 'đoạn', 'lớp', 'bác'}
PERSON_WORDS = {'bạn', 'anh', 'em', 'ông', 'bà', 'chị', 'nàng', 'ngươi'}
ABSTRACT_NOUN_MARKERS = {'sự', 'điều', 'mối', 'niềm'}
SPATIAL = {'bên', 'phía', 'trước', 'sau'}
QUANTIFIERS = PLURALS | {'một', 'nhiều', 'mọi', 'mấy', 'hai', 'con'}
ONSET = re.compile(r'(?:[bdghklmnpqrstvx]|tr)$')
PREPOSITIONS = {'of', 'to', 'in', 'on', 'at', 'for', 'from', 'with'}
DEMONSTRATIVES = {'this', 'these', 'those'}
GREETINGS = {'hello', 'hi', 'welcome'}
WORD_END = re.compile(r'[^\W\d_]+$')


def vietnamese_mark(text):
    n = unicodedata.normalize('NFD', text.lower())
    return (any(c in n for c in ('đ', '\u031b', '\u0309', '\u0323')) or
            ('\u0302' in n and any(c in n for c in '\u0300\u0301\u0303')))


def vowel_fragment(text):
    # A single toned vowel, not a compound/horned vowel.
    if len(text) != 1:
        return False
    n = unicodedata.normalize('NFD', text)
    return (n[0] in 'aeiouy' and
            any(c in n for c in '\u0300\u0301\u0309') and
            not any(c in n for c in '\u0302\u0306\u031b'))


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    first = carry is None or carry[0] != doc
    if first:
        strength, previous, dots_only = 0.0, '', True
    else:
        _, strength, previous, dots_only = carry
        strength *= 0.96

    starts_word = bool(token and (token[0].isspace() or not previous))
    match = WORD_END.search(previous + token.lower())
    word = match[0][-24:] if match else ''
    if vietnamese_mark(token) or word in PLURALS:
        strength = min(1.0, strength + 0.5)
    vietnamese = strength > 0.2
    value = 0.0

    if word in PLURALS:
        value = -5.5
    elif word in CLASSIFIERS and (word != 'con' or
                                  (vietnamese and token.startswith(' '))):
        value = -5.0
        if word == 'con':
            value = -3.4
        elif word == 'cuộc':
            value = -6.0
    elif word == 'người':
        value = -1.5 if previous in QUANTIFIERS else -3.6
    elif vietnamese:
        if word in NOMINALS:
            value = -2.0
        elif word in {'cách', 'mái', 'giải', 'tiếng', 'cửa'}:
            value = -1.3
        elif word in PERSON_WORDS or word in ABSTRACT_NOUN_MARKERS:
            value = -0.7
        elif word in {'một', 'số', 'vài'}:
            value = -0.4
        elif word in SPATIAL:
            value = -3.0 if word == 'trước' else -1.6
        elif word in {'ngày', 'nhiều', 'bước', 'phần', 'mấy', 'mỗi'}:
            value = -1.5
        elif vowel_fragment(token.strip().lower()):
            value = 1.6
        elif starts_word and ONSET.fullmatch(token.strip().lower()):
            value = 1.0
            if token.strip().lower() in {'h', 'k', 'r'}:
                value = 2.5

    if first:
        # Without a preceding phrase, most negative noun responses are weaker.
        if value < -1.0 and word != 'cuộc':
            value *= 0.5
        raw = token.strip().lower()
        if any('HANGUL' in unicodedata.name(c, '') for c in token):
            value = 1.7
        elif raw in PREPOSITIONS or raw == 'the':
            value = -0.4
        elif raw in DEMONSTRATIVES or raw in GREETINGS:
            value = 0.9
        elif raw in {'a', 'an'} and token.startswith(' '):
            value = 0.65
        elif len(raw) == 1 and raw.isascii() and raw.isalpha():
            value = -0.25
        elif token.isspace():
            value = -0.8 if '\t' in token else -0.3
            if '\n' in token:
                value = 0.15
        elif token.startswith(('#', '"""', '/*', '**')):
            value = 0.4 if token == '#' else 1.0
    dots_only = dots_only and token == '··'
    if dots_only:
        value = 2.2

    # Carry the current word fragment and language cue, resetting at documents.
    return (doc, strength, word, dots_only), value

programs.haiku:
"""Vietnamese noun-phrase openers: plural and classifier words that begin a noun phrase
("các", "những", "cái", "chiếc", "cuộc") are strongly negative, and a second group of
nouns and quantifiers that take a following noun is moderately or weakly negative."""
from collections.abc import Mapping

READS = ()

STRONG = {" các", " Các", " những", " Những", " cái", " chiếc", " cuộc"}
MEDIUM = {" người", " trước", " việc", " bác", " loại"}
WEAK = {" cách", " sau", " phần", " sự", " điều", " bản", " ngày", " bên", " cửa", " nhiều",
        " mỗi", " mấy", " tiếng", " cặp", " đoạn"}


def step(carry, prefix, upstream: Mapping):
    tok = prefix.token_strings[-1]
    if tok in STRONG:
        value = -5.5
    elif tok in MEDIUM:
        value = -2.5
    elif tok in WEAK:
        value = -1.3
    else:
        value = 0.0
    return carry, float(value)

programs.sol:
"""Approximate a negative single-letter / initial / variable signal.

Word-initial alphabetic letters are strongly negative; lowercase word
continuations are mostly quiet. Case changes, scripts, contractions and
single-letter function words refine this rule. English 'a' stays stronger
in mathematical or variable-introducing contexts. Word frequencies help
recognize ordinary uses of 'a', 'I', 'e', 'y' and 'o'. Other tokens are near
zero, with small priors for undecodable fragments and the article 'an'.
This is a lexical approximation, not a model of every letter's strength.
"""
import re
import unicodedata
from functools import lru_cache
import regex
from wordfreq import zipf_frequency

READS = ()
LETTER = regex.compile(
    r'[^\p{L}\p{N}]*([\p{Latin}\p{Cyrillic}\p{Greek}'
    r'\p{Arabic}\p{Hebrew}])[^\p{L}\p{N}]*\Z'
)
CLAUSE_WORDS = set('if that when whether because although while'.split())
ARTICLE_FRIENDLY = set('as in into like within'.split())


@lru_cache(maxsize=16384)
def frequency(word, language):
    return zipf_frequency(word.lower(), language)


@lru_cache(maxsize=16384)
def letter(token):
    match = LETTER.fullmatch(token)
    return match[1] if match else ''


SYMBOL_CUES = set(
    'let var variable variables parameter parameters '
    'coefficient coefficients'.split()
)
MATH_CONTEXT = re.compile(r'\\(?:frac|sqrt|lim|sum)|[=^²³₀₁₂]')


def predict(token, previous, tail):
    token = unicodedata.normalize('NFKC', token)
    # Escaped newlines may share a token with the next letter.
    # Exclude TeX commands: \\ne, \\ni, \\nu and the prefix of \\not.
    if (previous.endswith('\\') and len(token) == 2
            and token[0] == 'n' and token not in ('ne', 'ni', 'nu', 'no')):
        if token[1].isascii() and token[1].isalpha():
            return -1.7
    if (re.fullmatch(r'\\x[a-fA-F]', token)
            or (previous.endswith(('0', '\\'))
                and re.fullmatch(r'x[a-fA-F]', token))):
        return -0.95
    ch = letter(token)
    if not ch:
        if '\ufffd' in token:
            return -0.15
        return 0.22 if token == ' an' else 0.0
    if token.startswith('\\'):
        return -0.18 if token == '\\n' else 0.0
    if ((token.startswith(("'", '’')) and ch in 'stdm')
            or (previous.endswith(("'", '’')) and token in 'stdm'
                and len(tail) > 1 and tail[-2].isalpha())):
        return -0.03
    if token == 'n' and previous.endswith('\\'):
        return 0.10
    if token == 'x' and previous.endswith('0'):
        return 0.0
    boundary = (token[0] != ch or not previous
                or not previous[-1].isalpha()
                or tail.endswith(('\\n', '\\t', '\\r')))
    if not boundary:
        if ch.isupper():
            # Camel-case initials are stronger than acronym continuations.
            return -0.65 if previous[-1:].islower() else -0.25
        return -0.06
    if ch in 'ияИя':
        return 0.0 if ch.islower() else -0.2
    if regex.fullmatch(r'\p{Greek}', ch):
        return -0.5
    if regex.fullmatch(r'[\p{Arabic}\p{Hebrew}]', ch):
        return -0.7
    if not ch.isascii():
        if regex.fullmatch(r'\p{Latin}', ch):
            return -0.24
        return -1.0
    words = re.findall(r'[^\W\d_]+', tail)
    word = words[-1].lower() if words else ''
    prev = previous.strip().lower()
    if token == ' a':
        if prev in SYMBOL_CUES:
            return -1.5
        if MATH_CONTEXT.search(tail) and prev not in ARTICLE_FRIENDLY:
            return -0.9
        if prev in ARTICLE_FRIENDLY:
            return 0.05
        if prev in CLAUSE_WORDS:
            return -0.8
        if previous.endswith(("'s", '’s')):
            return -0.15
        if previous.endswith(','):
            return -0.65
        if previous.strip() in '=+-*/' or len(prev) == 1:
            return -1.5
        english = frequency(word, 'en')
        romance = max(frequency(word, lang)
                      for lang in ('pt', 'fr', 'es', 'it'))
        if previous[-1:].isalpha() and english >= max(3.5, romance):
            return -0.2
        return -1.1
    if ch == 'I' and token.strip() == 'I':
        if previous.endswith(','):
            return -0.36
        if previous.endswith(('.', '!', '?')):
            return -0.58
        if previous[-1:].isalpha() and frequency(word, 'en') >= 5:
            return -0.25
        return -0.85
    if token in (' e', ' y', ' o'):
        lang = 'es' if ch == 'y' else 'pt'
        native = frequency(word, lang)
        if ch == 'e':
            native = max(native, frequency(word, 'it'))
        if native > frequency(word, 'en') + 1:
            return -0.2 if ch != 'o' else -0.7
        return -1.2 if ch == 'e' else -1.05
    if ch.isupper():
        return -1.15
    if token[0] == '.' or (token == ch and previous[-1:].isdigit()):
        return -1.05
    return -1.3


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    first = carry is None or carry[0] != doc
    previous, tail = ('', '') if first else carry[1:]
    value = 0.35 if first else predict(token, previous, tail)
    return (doc, token, (tail + token)[-100:]), value

"""Approximate a software-usage and documentation signal.

Recognize interface/grammar vocabulary, capability phrases, and documentation
or source-code links. Test/implementation vocabulary has weaker or negative
values. Surface adjustments distinguish prose, identifier pieces and capitals.
The short context also recognizes named constructs and document-title metadata.
This is partial: most text stays near zero, without a per-token lookup.
It misses much of the component's lexical and contextual variation.
"""
import re

READS = ()

# Each named concept has: words; base; space, path and ALL-CAPS adjustments.
GROUPS = (
    # interface
    ("api function functionalities functionality functions method methods".split(),
     0.13, -0.04, 0, 0.37),
    # parameters
    ("argument arguments keyword keywords parameter parameters".split(),
     0.06, 0.22, 0, -0.15),
    # grammar
    ("declaration declarations literal literals namespace namespaces syntax".split(),
     0.29, 0.1, -0.33, 0.31),
    # capability
    (("allow allows enable enables feature "
      "features support supported supporting supports").split(),
     0.16, 0.15, 0, 0),
    # documentation
