        if prose and not text.startswith(('.', '_', '(', '[')):
            language += language_evidence(oldword)
        if oldword in EN_WORDS:
            language -= 0.25
        word = words[0].lower() if words else ''
        count = 1
        k = matches[0].start() if matches else 0
        prose = ((k > 0 and text[k-1].isspace()) or
                 (k == 0 and (pos == 0 or bool(previous and
                                              previous[-1].isspace()))))
    if len(words) > 1:
        for w in words[:-1]:
            language += language_evidence(w.lower())
            language -= 0.25 * (w.lower() in EN_WORDS)
        word, count = words[-1].lower(), 1
        k = matches[-1].start()
        prose = k > 0 and text[k-1].isspace()
    language = max(-0.5, min(1.5, language))
    local = max(0.0, min(1.0, language + 0.5 * (
        prose and language_evidence(word) > 0)))

    # Word shapes determine the signed activation in that language context.
    s = text.strip().lower()
    value = 0.0
    if s.isascii() and s.isalpha():
        shape = 0.0
        if not continues:
            if s == 'di':
                shape = -1.25
            elif s.startswith('di'):
                shape = -4.4
            elif s == 'd':
                shape = -1.5
            elif s in {'men', 'mem', 'mel'}:
                shape = 0.8
        elif oldword == 'd':
            shape = -6.8 if s.startswith('i') else -0.45
        elif oldword.startswith('di'):
            if pieces == 1:
                shape = -2.8
            elif pieces == 2:
                shape = -1.4
            elif pieces == 3:
                shape = -1.35
        value = local * shape
        value += 0.47 * local * shared_word(s)
        value -= 0.02 * (1-local) * language_overlap(s)
        if not word.startswith('di'):
            ending = bool(LOAN_ENDING.search(word))
            if (word.endswith('ik')
                    and zipf_frequency(word[:-2] + 'ic', 'en') > 2.5):
                ending = True
            if continues and ending:
                value += local * 2.3
            value += local * 0.37 * adapted_word(word)
        if s in MONTHS and text.strip()[0].isupper():
            value += 3.0 * local

    # Repeated typographical dots, and fixed document-opening formats.
    if len(s) >= 2 and set(s) == {'·'}:
        value = 2.27 if pos == 0 or set(previous.strip()) == {'·'} else 0.21
    if pos == 1 and previous.lower() == 'title' and text == ':':
        value = -2.85
    if pos == 0:
        if len(s) == 1 and s.isascii() and s.isalpha():
            value -= 0.28
        if s.isascii() and s.isdigit():
            value -= 0.32
        if text.isspace() and '\n' in text:
            value -= 0.59 / text.count('\n')
        if text.startswith(('//', '/*')):
            value += 0.7
        if text.startswith('#'):
            value += 0.32
        if text.startswith(('\"', "'")):
            value -= 0.27
        if text.startswith('{'):
            value -= 1.15
        if text == ' .':
            value = 3.95
        elif text == '//\n':
            value = 2.31

    if not text or not (text[-1].isascii() and text[-1].isalpha()):
        if prose:
            language = max(-0.5, min(1.5, language + language_evidence(word)))
        if word in EN_WORDS:
            language = max(-0.5, language - 0.25)
        word, count, prose = '', 0, True
    return (doc, pos+1, word, count, language, text, prose), float(value)

"""Predict a formatting response: spaces versus key/value separators.

A separate ASCII space is usually positive, reduced where earlier separate
spaces were followed by more whitespace. Line breaks and preceding digits
have their own response. Counts reset at document boundaries.

Colons ending quoted keys, object-field colons, and mapping arrows are
negative.  Doubled backslashes are positive as escapes, negative in LaTeX.
Periods after digits get small negative values, stronger at line start.
Other tokens are zero. The small parser is only a formatting heuristic.
"""
import re

READS = ()
FIELD = re.compile(r'(?:^|[{,])\s*(?:[A-Za-z_$][\w$]*|\d+)\s*$')
NON_OBJECT = re.compile(
    r'(?:\\[A-Za-z]+|\b(?:interface|class|struct|type|enum)\s+[A-Za-z_$][^{};:]*)'
    r'\{[^{}]*$'
)
LINE_NUMBER = re.compile(r'(?m)^[ \t]*\d+\t[ \t]*')
LATEX = re.compile(
    r'\\(?:begin|end|frac|pmatrix|matrix|left|right|qquad|vec|ldots|mbox|big)\b'
)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        previous, spaces, extra, tail, brackets = '', 0, 0, '', ''
    else:
        _, previous, spaces, extra, tail, brackets = carry
    if previous == ' ':
        spaces += 1
        extra += bool(token[:1].isspace())

    value = 0.0
    if token == ' ':
        fraction = extra / max(1, spaces)
        blank = previous.isspace()
        punctuation = bool(previous) and not any(c.isalnum() for c in previous)
        if previous.endswith(r'\n'):
            value = -1.9
        elif '\n' in previous:
            value = -0.9
        elif previous.isdigit():
            value = -0.1 - 0.6 * fraction
        elif blank:
            value = 0.7 - 0.85 * fraction
        elif punctuation:
            value = 0.5 - 0.9 * fraction
        else:
            value = 0.3 - 1.3 * fraction
    elif token.endswith(('":', "':")):
        value = -1.9 if token.endswith('":') else -1.5
    elif token == ':':
        # Object keys after a brace or comma; ignore printed line numbers.
        view = tail.replace(r'\n', '\n').replace(r'\t', '\t')
        view = LINE_NUMBER.sub('', view)
        if (brackets.endswith('{') and FIELD.search(view)
                and not NON_OBJECT.search(view)):
            value = -2.0
    elif token == ' =>':
        if tail.rstrip().endswith(('"', "'")):
            value = -1.75
        elif '$' in tail[-100:] or '::' in tail[-60:]:
            value = -0.7
    elif token.endswith('\\\\'):
        if LATEX.search(tail) or token.startswith((' ', '}')):
            value = -2.1
        else:
            value = 1.1
    elif token == '.' and previous.isdigit():
        line = tail.rsplit('\n', 1)[-1].strip()
        value = -0.35 if line.isdigit() else -0.04

    # Brackets are tracked even in quoted code, so embedded snippets also work.
    for ch in token:
        if ch in '{[(':
            brackets = (brackets + ch)[-64:]
        elif ch in '}])':
            opening = {'}': '{', ']': '[', ')': '('}[ch]
            at = brackets.rfind(opening)
            if at >= 0:
                brackets = brackets[:at]
    tail = (tail + token)[-512:]
    return (doc, token, spaces, extra, tail, brackets), value

"""Approximate error reports and output-introducing markers.

Diagnostic words become stronger near error-producing operations, while mathematical
errors and code identifiers are discounted.  Separate rules cover colons, stack
traces, documentation tags, tool-call JSON and chat markers.  Small boundary
and filler rules handle initial comment lines and repeated middle dots.
Unmatched text is near zero; a short context buffer resets for each document.
"""
import re

READS = ()
ERRORS = {'error', 'errors', 'warning', 'warnings'}
FAILURES = {'fail', 'fails', 'failed', 'failing', 'failure', 'failures', 'cannot'}
ISSUES = {'issue', 'issues', 'bug', 'bugs', 'crash', 'crashes', 'stuck', 'missing'}
RESULTS = {'result', 'results', 'output', 'outputs', 'expected', 'unexpected'}
REPORTS = {
    'say', 'says', 'said', 'shows', 'showed', 'indicates', 'returns', 'returned',
    'produces', 'produce', 'received', 'got', 'getting', 'gives', 'giving',
}
TECHNICAL = re.compile(
    r'error|warning|exception|fail|syntax|traceback|compil|npm|pytest|debug|'
    r'deprecat|runtime|stack trace', re.I)
EMISSION = re.compile(
    r'\b(get|gets|getting|got|throw|throws|threw|throwing|raise|raises|raised|'
    r'raising|reproduce|reproduced|reproducing|trigger|triggers|triggered|'
    r'encounter|encountered|encountering)\b', re.I)
NON_DIAGNOSTIC = re.compile(
    r'\b(standard|mean|squared|human|spelling|prediction|statistical|systematic|'
    r'residual|margin|absolute|relative|measurement)\b', re.I)
SOURCE_FILE = re.compile(
    r'\.(py|js|ts|go|rs|java|cpp|cc|c|h|rb|swift|php|cs)$', re.I)


def predict(text, previous, recent, position):
    word, prev = text.strip().lower(), previous.strip().lower()
    technical = bool(TECHNICAL.search(recent))
    value = 0.0

    if word in ERRORS or word == 'err' and text.strip().isupper():
        value = 1.3 if text[:1].isspace() else 0.7
        if prev in {'the', 'this', 'that'}:
            value += 0.9
        if EMISSION.search(recent):
            value += 0.5
        if technical:
            value += 0.3
        if previous.isspace() or previous.endswith(':'):
            value += 0.6
        if prev in {',', 'err', 'as', 'of', 'and', 'in', 'if', '=>'}:
            value -= 1.0
        if NON_DIAGNOSTIC.search(recent[-50:]):
            value -= 1.0
    elif text.strip().endswith(('Error', 'Exception', 'Warning')):
        value = 1.0
    elif word in FAILURES:
        value = 1.7 if word == 'failing' else 0.5
        if text.strip() == 'Cannot':
            value = 1.5
        if technical:
            value += 0.25
    elif word in ISSUES:
        value = 0.6 if word in {'issue', 'issues'} else 0.4
    elif word in RESULTS:
        value = 0.3 + 0.4 * (prev in {'the', 'same', 'test'})
    elif word in REPORTS:
        value = 0.2 + 0.4 * technical
        if prev in {'it', 'this', 'that'}:
            value += 0.4
        if prev in {'he', 'she', 'who', 'and', ',', ',"'}:
            value -= 0.2
    elif word in {'work', 'works', 'working', 'worked'}:
        value = 0.1
        if prev in {'not', "'t", '’t', 'still', 'should', 'stop', 'stopped'}:
            value += 1.1
    elif word in {'correctly', 'properly', 'successfully', 'correct', 'invalid'}:
        value = 0.8 if word in {'correctly', 'properly'} else 0.5

    if ':' in text and not any(c.isalnum() for c in text):
        value = 0.3 - 0.15 * ('\n' in text)
        if prev in ERRORS or prev.endswith(('error', 'exception', 'warning')):
            value += 2.0
        if SOURCE_FILE.search(previous):
            value += 0.7
        if previous.strip().isdigit():
            value += 0.3
        if prev == 'title':
            value = 5.3 if position == 1 else 0.9
        if text.startswith(']') and technical:
            value += 1.8
    if text == '{"':
        value = 0.95 if '<tool_call>' in recent else 0.2
    if text == '</think>':
        value = 0.66
    if text == '<tool_call>':
        value = 0.16
    if word == '@' and previous.strip() in {'*', '/**', '///'}:
        value = 0.8
    if word == 'param' and any(c in previous for c in '@<\\'):
        value = 1.0
    if word == 'at' and (
        previous.isspace() and len(previous) > 1 or '\t' in text
    ):
        value = 2.2
    if text.count('\n') >= 3:
        value += 0.3
    if text and set(text) == {'·'} and (
        position == 0 or set(previous) == {'·'}
    ):
        value = -1.45
    if position == 0:
        value -= 0.15 * text.strip().isalpha()
        if text == '//\n':
            value = 8.9
    return value


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or doc != carry[0]:
        position, previous, recent = 0, '', ''
    else:
        _, position, previous, recent = carry
    text = prefix.token_strings[-1]
    value = predict(text, previous, recent, position)
    return (doc, position + 1, text, (recent + text)[-160:]), value

programs.haiku:
"""Error and failure talk.

The component fires on the words a software error or warning is announced with ("error", "warning",
"failing", "issue"), on the colon that introduces an error message ("TypeError:", "error:"), on the
"at" that opens a stack-trace line, and on code-output punctuation ("{\"", "\":", "::", " @").
Its strongest activity is in a software-debugging context; "error" in maths ("prediction error") is weak.
Otherwise it is near zero, with a small negative value on runs of middle dots.
"""
import re

# value of an error word written with a leading space (" error"); unspaced forms count half
ERROR_WORDS = {"error": 1.2, "errors": 1.0, "warning": 1.3, "warnings": 2.0, "fail": 0.4, "failed": 0.4,
               "failing": 1.4, "fails": 0.5, "failure": 0.1, "crash": 0.6, "crashes": 1.1,
               "unexpected": 0.7, "invalid": 0.3, "issue": 0.4, "issues": 0.2, "cannot": 0.6}
# words about whether something worked or what it printed
OUTCOME_WORDS = {"work": 0.15, "works": 0.15, "working": 0.2, "worked": 0.2, "correct": 0.2,
                 "correctly": 0.6, "expected": 0.3, "result": 0.2, "output": 0.2, "says": 0.4,
                 "got": 0.2, "getting": 0.15, "message": 0.2, "missing": 0.2, "nan": 0.3}
# punctuation and tokens of code, JSON and tool output
CODE_TOKENS = {"::": 0.25, '{"': 0.9, '":': 0.3, "]:": 0.6, ":\n": 0.2, " @": 0.35, "param": 0.9}
FILE_EXTENSIONS = {".js", ".ts", ".py", ".go", ".rs", ".java", ".php"}
STACK_LINE = re.compile(r"\s*at\b")
READS = ()
SOFTWARE_WORDS = {"code", "script", "function", "test", "tests", "syntax", "run", "running", "bug", "reproduce",
                  "file", "command", "compile", "build", "install", "server", "module", "package", "library",
                  "console", "terminal", "version", "stack", "traceback", "program", "api", "request", "json"}
MATH_WORDS = {"prediction", "classification", "allowable", "maximum", "minimum", "probability", "estimate",
              "regression", "variance", "tolerance", "measurement", "approximation", "sample", "numerical",
              "absolute", "relative", "squared", "standard"}


def error_value(token):
    """How strongly one token is an error word (0 for most tokens)."""
    word = token.strip()
    if word == "ERR":
        return 1.5
    if word.endswith("Error") and len(word) > 5:
        return 1.2  # TypeError, ValueError, ...
    value = ERROR_WORDS.get(word.lower(), 0.0)
    return value if token[:1] == " " else value / 2  # ".Error", "_error" are code, not words


def step(carry, prefix, upstream):
    # carry: (text of the current line so far, tokens since the last error word); None at a document start
    toks = prefix.token_strings
    cur = toks[-1]
    prev = toks[-2] if len(toks) > 1 else ""
    new_doc = len(toks) == 1 or prefix.document_ids[-1] != prefix.document_ids[-2]
    line, since = ("", None) if new_doc or carry is None else carry
    since = None if since is None else since + 1
    line_before = line
    line = cur.split("\n")[-1] if "\n" in cur else line + cur
    in_stack_line = bool(STACK_LINE.match(line_before)) and "\n" not in cur
    recent = since is not None and since <= 20   # an error word appeared within the last 20 tokens

    value = error_value(cur)
    if value:
        # an error word in a maths context (prediction error, tolerance) is weak; in a software context strong
        words = {w.strip().lower() for w in toks[-16:-1]}
        if words & MATH_WORDS and not words & SOFTWARE_WORDS:
            value *= 0.3
        elif words & SOFTWARE_WORDS:
            value *= 1.5
        return (line, 0), value
    if cur == ":":
        if error_value(prev):
            value = 2.5  # the colon right after an error word
        elif in_stack_line:
            value = 1.5  # file:line:column in a stack trace
        elif prev in FILE_EXTENSIONS:
            value = 1.0
        elif recent:
            value = 0.6
        else:
            first = line_before.strip()[:1]
            value = 0.4 if first.islower() else 0.1 if first.isupper() else 0.25
    elif line_before.strip() == "" and cur.strip() == "at":
        value = 2.5  # "at" opening a stack-trace line
    elif cur in CODE_TOKENS:
        value = CODE_TOKENS[cur]
    elif cur.strip().lower() in OUTCOME_WORDS:
        value = OUTCOME_WORDS[cur.strip().lower()]
    elif cur and set(cur) == {"·"}:
        value = -1.5  # runs of middle dots, a leader filler
    else:
        value = 0.0
    return (line, since), value

programs.sol:
"""Surface cues for conversion and representation changes.

Strong responses occur at to/from/as fragments inside program identifiers.
Ordinary prepositions are weaker, but conversion, transfer, import and cast
contexts strengthen them. An identifier-attached 2 is another conversion cue.
A few negative surface responses are included separately. These are average
responses to readable cues, not inferred types or a full language parser.
"""
import re

READS = ()
# Word stems cover inflections and split pieces of program identifiers.
CHANGE = tuple(('convert conversion transform translat cast pars encod decod '
                'serializ deserializ stringify stringification format round '
                'map chang').split())
EXPLICIT = tuple('convert conversion translat cast encod decod serializ '
                 'deserializ'.split())
TRANSFER = tuple('read writ load sav export import copy copi move moving '
                 'send upload download return'.split())
COMPLEMENTS = set(('need needs needed want wants wanted have has had going '
                   'able ability trying try tries tried used use uses according '
                   'due order up down tend tends like likes seem seems ought '
                   'supposed designed intended required important possible '
                   'necessary difficult easy wish wishes ready belong belongs')
                  .split())
TYPES = set(('str string char byte bytes int integer float double decimal bool '
             'boolean vector vec date datetime hex bin binary array list').split())
DIRECTIONS = {'to', 'from', 'as', 'for', 'into'}
NAME = re.compile(r'^(?:[tT]o|[fF]rom|[aA]s|[pP]arse)[A-Z_]')


def response(token, previous, recent, line):
    core = token.strip()
    word = core.lstrip('._-(')
    low = word.lower()
    if len(core) >= 2 and set(core) == {'·'}:
        return -1.82
    if low in {'typeof', 'type_of'} and core.startswith(('.', '_')):
        return -1.86
    if low in {'download', 'downloading', 'downloaded'}:
        return -0.26
    named = bool(NAME.match(word))
    verbs = {'cast', 'atof', 'atoi', 'repr', 'stringify', 'serialize',
             'deserialize', 'decode', 'encode', 'parsefloat', 'parseint'}
    if named or low in verbs:
        value = 0.38 if named else 0.11
        if core.startswith('.'):
            value += 0.97
        if low in {'parsefloat', 'parseint', 'atof', 'atoi'}:
            value += 1.48
        if low in {'stringify', 'serialize', 'deserialize'}:
            value += 0.56
        return value
    if low not in DIRECTIONS and core != '2' and '`' not in core:
        return 0.0

    words = re.findall(r'[A-Za-z]+', recent.lower())
    last = words[-1] if words else ''
    change = any(w.startswith(CHANGE) for w in words[-8:])
    explicit = any(w.startswith(EXPLICIT) for w in words[-8:])
    transfer = any(w.startswith(TRANSFER) for w in words[-6:])
    code = bool(re.search(r'[{}_]|::|->|//', recent[-100:]) or
                line.startswith('    '))
    escaped_space = bool(re.search(r'\\[ntr]$', recent))
    if core == '2':
        if previous[-1:].isalpha() and not escaped_space:
            value = 0.45 - (0.35 if len(last) == 1 else 0.0)
            value += 0.47 if code else 0.0
            value += 0.60 if last in TYPES else 0.0
            value += 0.63 if change or 'cast' in last else 0.0
            value += 0.40 if transfer else 0.0
            if re.search(r'\\x[0-9a-f]*$', recent, re.I):
                value -= 0.57
            return value
        if previous.endswith('_'):
            return 0.21
        shell = re.search(r'&&|\||\b(?:cargo|pytest|python|bash|npm|go test)\b',
                          line)
        return 0.20 if (previous.isspace() or escaped_space) and shell else -0.02
    if low not in DIRECTIONS:
        return -0.38 if len(core) < 5 and last in {'the', 'a', 'an', 'to'} else 0.0
    if core == 'As' and previous[-1:].isupper():  # e.g. GPAs, RNAs
        return -0.17

    member = core.startswith(('.', '_')) or (
        not token[:1].isspace() and previous.endswith(('.', '_', '::')))
    camel = (not token[:1].isspace() and core[:1].isupper() and
             not core.isupper() and previous[-1:].isalpha() and
             not escaped_space)
    if member or camel:
        if low in {'for', 'into'}:
            return 0.3 if low == 'for' else 0.8
        value = {'to': 3.26, 'from': 2.53, 'as': 2.24}[low] if member else {
            'to': 1.55, 'from': 2.55, 'as': 2.60}[low]
        return value + (0.99 if last in TYPES else 0.0)
    value = 0.45 if core.startswith(('-', '(')) else {
        'to': 0.04, 'from': 0.05, 'as': -0.02}.get(low, 0.0)
    if low in {'for', 'into'}:
        return value + (0.21 if low == 'into' and change else 0.0)
    if code:
        value += {'to': 0.26, 'from': 0.36, 'as': 0.20}[low]
    if change:
        value += {'to': 0.10, 'from': 0.18, 'as': 0.33}[low]
        if last.startswith(CHANGE):
            value += {'to': 0.14, 'from': -0.06, 'as': -0.10}[low]
    elif transfer:
        value += {'to': 0.20, 'from': 0.27, 'as': 0.23}[low]
        if low == 'from' and last.startswith(TRANSFER):
            value += 0.66
    if explicit:
        value += {'to': 0.74, 'from': 0.51, 'as': -0.12}[low]
        if last.startswith(EXPLICIT):
            value += {'to': 0.93, 'from': 0.23, 'as': -0.03}[low]
    if last in COMPLEMENTS and low in {'to', 'from'}:
        value -= 0.11
    if re.search(r'\bimport\b', line):
        value += 1.19 if low == 'as' else 0.32 if low == 'from' else 0.0
    if low == 'as' and ('except' in line or previous.rstrip().endswith(')')):
        value += 0.74
    if previous[-1:] in {'`', '"', "'"}:
        value += {'to': 0.42, 'from': 0.13, 'as': 0.21}[low]
    if low == 'as' and core[:1].isupper():
        value -= 0.095
    return value


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, recent, line = '', '', ''
    else:
        _, previous, recent, line = carry
    token = prefix.token_strings[-1]
    value = response(token, previous, recent, line)
    recent = (recent + token)[-160:]
    line = (line + token)[-250:].rsplit('\n', 1)[-1]
    return (doc, token, recent, line), float(value)

programs.haiku:
"""Component layers.1.mlp.down_proj:3388: a "to / from / as / into / 2" detector for code.

It fires on the short words to, from, as, into, and on the digit 2, when they are part of
a programming name or a code phrase rather than ordinary English:

- a method or attribute suffix joined by a dot or underscore (".to", "_from", ".as"):
  strongest, value 3;
- "to", "from" or "into" glued straight onto the word before them, with no space
  ("`to", "To"): value about 1;
- a space-separated " to" / " from" / " as" right after a conversion, write, export or copy
  word or file/data noun ("convert to", "write the PID to", "export to file"), or right
  after an import alias or except clause ("import numpy as", "except OSError as"): value 1.2;
  the same words with such a verb a few words back ("write the PID to"): value 0.4;
  in ordinary prose they stay near 0;
- a digit 2 glued to a name of three or more letters ("copy2", "pbkdf2", "VARCHAR2"): value 1;
  glued to a one- or two-letter name ("x2"): value 0.2.

Everything else predicts 0. The values are rough means of the component's activation on
training text, not fitted per token.
"""

import re

READS = ()

SUFFIX_WORDS = {"to", "from", "as", "into"}
TRANSFER_WORDS = {
    "convert", "converted", "converting", "write", "writes", "written", "writing",
    "export", "exported", "copy", "save", "round", "rounded", "translate", "cast",
    "output", "print", "dump", "file", "files", "data", "content", "directory",
}
ALIAS_PREV = {"numpy", "pandas", "np", "pd", "Exception", "Error", "OSError", "IOError"}
WINDOW = 8  # how many earlier tokens count as "a few words back"


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    word = tok.strip(" \t._").lower()
    n = len(prefix)
    # the last few words, within the same document
    recent = [
        prefix.token_strings[i].strip()
        for i in range(max(0, n - 1 - WINDOW), n - 1)
        if prefix.document_ids[i] == prefix.document_ids[-1]
    ]
    prev = recent[-1] if recent else ""
    if word in SUFFIX_WORDS and tok.startswith((".", "_")):
        value = 3.0
    elif word in SUFFIX_WORDS and not tok.startswith(" "):
        value = {"to": 0.9, "from": 0.8, "into": 0.4}.get(word, 0.0)
    elif word in SUFFIX_WORDS:
        if prev in TRANSFER_WORDS or prev in ALIAS_PREV or prev.endswith((")", "')")):
            value = 1.2
        elif any(w in TRANSFER_WORDS for w in recent):
            value = 0.4
        else:
            value = 0.05
    elif tok == "2" and prev[-1:].isalpha():
        # a digit glued to a name: long names ("copy2", "pbkdf2") fire, short ones less
        tail = "".join(prefix.token_strings[max(0, n - 4) : n - 1])
        name = re.search(r"[A-Za-z]*$", tail).group()
        value = 1.0 if len(name) >= 3 else 0.2
    else:
        value = 0.0
    return carry, value

programs.sol:
"""Approximate a genitive-particle signal, with a secondary type-boundary rule.

Japanese の and Korean 의 receive positive responses; the Japanese strength
also depends on the preceding script. For Chinese 的, English dictionary
glosses estimate the noun/verb/adjective/adverb mix of the longest preceding
word (up to five characters). Copular, modal, degree and aspect cues lower
its response, sometimes below zero. Particles merged into larger Chinese
tokens get weaker responses. Bare closing parentheses in Go signatures and
Java-style casts also get positive responses. Everything else is zero.

These are local grammatical heuristics, not a syntactic parser. They retain
700 bytes of recent text and reset that context at document boundaries.
"""
import re
import regex
from functools import lru_cache
import cedict
import wordnet
from opencc import OpenCC

READS = ()
SIMPLIFY = OpenCC('t2s')
MODALS = set('可能 可以 能够 应该 应当 必须 必需 需要 必要 不行 不够'.split())
CORRECTNESS = {'正确', '错误'}


@lru_cache(maxsize=16384)
def word_classes(word):
    """Vote among dictionary senses: noun, verb, adjective, adverb."""
    glosses = [g for g in cedict.glosses(word)
               if not g.startswith(('variant of ', 'old variant of ',
                                    'see ', 'CL:', 'surname '))]
    if not glosses:
        return None
    counts = dict.fromkeys(('noun', 'verb', 'adjective', 'adverb'), 0.)
    for gloss in glosses[:4]:
        for sense in gloss.split(';'):
            sense = re.sub(r'\([^)]*\)', '', sense).strip().lower()
            if sense.startswith('to '):
                parts = {'verb'}
            elif sense.startswith(('a ', 'an ', 'the ')):
                parts = {'noun'}
            else:
                parts = wordnet.parts_of_speech(sense)
                if not parts and ' ' in sense:
                    parts = wordnet.parts_of_speech(sense.split()[-1])
            for part in parts:
                counts[part] += 1. / len(parts)
    total = sum(counts.values())
    return tuple(c / total if total else 0. for c in counts.values())


def chinese_de(before):
    before = SIMPLIFY.convert(before)
    noun = verb = adjective = adverb = 0.
    for length in range(min(5, len(before)), 0, -1):
        parts = word_classes(before[-length:])
        if parts is not None:
            noun, verb, adjective, adverb = parts
            break
    value = 1.45 + .55*noun - .95*verb - 1.35*adjective - .75*adverb
    if re.search('[了过着]$', before):
        value -= .7
    if re.search(r'(?:不|得)[了到住完来去]$', before):
        value -= 1.5
    if re.search(r'(?:很|太|最|更|非常|十分|比较|这么|那么)[^，。的]{1,5}$', before):
        value -= .3
    clause = re.split(r'[。！？!?，,；;\n]', before)[-1]
    if '是' in clause:
        predicate = clause.rsplit('是', 1)[-1]
        value -= .7 + .8*verb + .8*adjective
        if len(predicate) <= 4:
            value -= 1.1
        if any(before.endswith(w) for w in MODALS | CORRECTNESS):
            value -= 3.1
        if re.match(r'(?:不?有|不?无)', predicate):
            value -= 2.3
    if re.search(r'(?:怎么|怎样|如何)[^，。的]{0,8}$', before):
        value -= .8
    if re.search(r'[》」”"）)]$', before):
        value += .4
    return value


def type_boundary(before, token):
    if token not in {')', '()', '{})', '>)', '[])'}:
        return 0.
    line = before.replace('\\n', '\n').replace('\\t', '\t').rsplit('\n', 1)[-1]
    line = line.replace('interface{}', 'interface').replace('struct{}', 'struct')
    if re.search(r'\bfunc\s+\(\s*\w+\s+\*?[\w.]+$', line):
        return 3.8
    if re.search(r'\bfunc\b[^{};]*$', line):
        if not re.search(r'\bfunc\s+(?:main|init)$', line):
            return 1.9 if re.search(r'\*\w+(?:\.\w+)?$', line) else 1.15
    if re.search(r'(?:=|\breturn|\()\s*\(\s*[A-Z][\w.<>\[\]]*$', line):
        return 1.1
    return 0.


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    old = b'' if carry is None or carry[0] != document else carry[1]
    before = old.decode('utf-8', errors='ignore')
    token = prefix.token_strings[-1]
    stripped = token.strip()
    if stripped == '的':
        value = chinese_de(before)
    elif stripped == 'の':
        if regex.search(r'\p{Script=Hiragana}$', before):
            value = 1.1
        elif regex.search(r'[\p{Script=Katakana}ー]$', before):
            value = 2.18
        elif regex.search(r'\p{Script=Han}$', before):
            value = 1.76
        else:
            value = 2.05
    elif stripped == '의':
        value = 1.48
    elif token.endswith('的') and not token.endswith('目的'):
        value = chinese_de(before + token[:-1])
        value *= .4 if value < 0 else .16
    elif token == '的一':
        value = .6
    else:
        value = type_boundary(before, token)
    recent = (old + prefix.token_bytes[-1])[-700:]
    return (document, recent), value

"""Approximate a lexical response to aid, bounty, and nourishing water.

The largest negative responses belong to a small Han-character family:
泽/沢 (beneficence, marsh), 润/潤 (moisten/enrich), 援 (aid), and 恩
(kindness), plus characters for deep water and favor. Two-character
compounds have weaker responses. Byte fragments are joined
before recognizing a character. A separate formatting response is the colon
immediately after a document-initial 'Title'. Initial Latin letters and
digits get small negative offsets; other unrecognized tokens predict zero.
"""
import codecs
from functools import lru_cache
from opencc import OpenCC

READS = ()

# Familiar lexical meanings, not tokenizer IDs.
BENEFICENCE = frozenset('泽沢')
SIMPLIFY = OpenCC('t2s')


@lru_cache(maxsize=20000)
def lexical(text):
    original = text.strip()
    s = SIMPLIFY.convert(original)
    if not s:
        return 0.0
    if s in BENEFICENCE:
        return -8.3 if original == '泽' else -7.2
    if s == '润':
        return -5.7 if original == s else -4.1
    if s == '援':
        return -7.2
    if s == '恩':
        return -2.5
    if s == '渊':
        return -7.1
    if s == '恵':
        return -1.9
    if s == '惠':
        return -0.4
    if len(s) != 2:
        return 0.0
    if any(c in s for c in BENEFICENCE):
        return -1.0
    if '润' in s:
        return -1.6
    if '援' in s:
        return -0.6 if s == '支援' else -2.6
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        decoder = codecs.getincrementaldecoder('utf-8')('replace')
        carry = (doc, 0, decoder, '')
    _, position, decoder, previous = carry
    text = decoder.decode(prefix.token_bytes[-1])
    value = lexical(text)
    if text == '援' and previous.endswith('応'):
        value = -3.2  # 応援: cheering someone on
    if position == 0 and text == 'Title':
        value = -2.0
    elif position == 1 and text == ':' and previous == 'Title':
        value = 18.39
    elif position == 0 and value == 0.0 and text:
        # Weak first-token effects are predictable from writing conventions.
        first = text[0]
        if first.isascii() and first.isupper():
            value = -0.26
        elif first.isascii() and first.islower():
            value = -0.07
        elif first.isdigit():
            value = -0.30
    return (doc, position + 1, decoder, text), float(value)
